package com.mutqin.app

data class HadithEntry(
  val id: Int, val title: String, val text: String, val narrator: String,
  val source: String, val reference: String, val grade: String, val explanation: String
)

val hadithEntries = listOf<HadithEntry>(
  HadithEntry(1,"الأعمال بالنيات","إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى.","عمر بن الخطاب رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 1؛ مسلم 1907","صحيح؛ متفق عليه","يبين الحديث أثر النية في الأعمال، وأن قصد القلب معتبر في الثواب وصحة كثير من الأعمال. ولا يعني أن النية وحدها تغني عن أداء العمل على وجهه الصحيح."),
  HadithEntry(2,"أركان الإسلام الخمسة","بُنِيَ الإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ.","عبد الله بن عمر رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 8؛ مسلم 16","صحيح؛ متفق عليه","يجمع الحديث أركان الإسلام الظاهرة الخمسة، ويبين مكانة الشهادتين والصلاة والزكاة والصوم والحج."),
  HadithEntry(3,"الدين النصيحة","الدِّينُ النَّصِيحَةُ. قُلْنَا: لِمَنْ؟ قَالَ: لِلَّهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ.","تميم الداري رضي الله عنه","صحيح مسلم","مسلم 55a","صحيح","النصيحة إخلاص وصدق وإرادة الخير، وتكون لله تعالى واتباع كتابه ورسوله وإرادة الخير للمسلمين بالحكمة والرفق."),
  HadithEntry(4,"الكلمة الطيبة وحفظ اللسان","مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 47a؛ وله روايات في الصحيحين","صحيح","يرشد الحديث إلى انتقاء الكلام النافع، وترك القول المؤذي أو الذي لا خير فيه، ويذكر في الرواية نفسها إكرام الجار والضيف."),
  HadithEntry(5,"محبة الخير للآخرين","لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.","أنس بن مالك رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 13؛ مسلم 45","صحيح؛ متفق عليه","يدعو الحديث إلى سلامة الصدر ومحبة الخير للناس، وترك الأنانية والحسد، وهو من كمال الإيمان الواجب.")  ,
  HadithEntry(6,"سلامة المسلمين من اللسان واليد","الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ.","عبد الله بن عمرو رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 10؛ مسلم 40","صحيح؛ متفق عليه","يربط الحديث كمال الإسلام العملي بكف الأذى عن الناس قولًا وفعلًا."),
  HadithEntry(7,"التيسير والتبشير","يَسِّرُوا وَلَا تُعَسِّرُوا، وَبَشِّرُوا وَلَا تُنَفِّرُوا.","أنس بن مالك رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 69؛ مسلم 1734","صحيح؛ متفق عليه","يرشد الحديث إلى الرفق والتيسير المنضبط بالشرع في التعليم والتعامل، دون إسقاط الواجبات."),
  HadithEntry(8,"الطهارة شطر الإيمان","الطُّهُورُ شَطْرُ الإِيمَانِ.","أبو مالك الأشعري رضي الله عنه","صحيح مسلم","مسلم 223","صحيح","يبين فضل الطهارة ومكانتها، وتفصل كتب الفقه أنواعها وأحكامها."),
  HadithEntry(9,"الرحمة بالخلق","مَنْ لَا يَرْحَمُ لَا يُرْحَمُ.","جرير بن عبد الله رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 6013؛ مسلم 2319","صحيح؛ متفق عليه","يدعو الحديث إلى الرحمة بالناس والرفق بهم، والرحمة خلق عام لا يقتصر على فئة دون أخرى."),

  HadithEntry(10,"الدلالة على الخير","مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ.","أبو مسعود الأنصاري رضي الله عنه","صحيح مسلم","مسلم 1893","صحيح","فيه فضل إرشاد الناس إلى الخير، وأن الدلالة النافعة سبب للأجر."),
  HadithEntry(11,"الرفق","إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ.","عائشة رضي الله عنها","صحيح مسلم","مسلم 2593","صحيح","يبين فضل الرفق في التعامل وأنه خلق محبوب."),
  HadithEntry(12,"إماطة الأذى","إِمَاطَةُ الأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ.","أبو هريرة رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 2989؛ مسلم 1009","صحيح","يدخل في أعمال الخير ما ينفع الناس ويحفظ سلامتهم."),
  HadithEntry(13,"الحياء","الْحَيَاءُ مِنَ الإِيمَانِ.","عبد الله بن عمر رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 24؛ مسلم 36","صحيح","الحياء خلق يحمل على الخير ويمنع من القبيح، وليس عذرًا لترك تعلم الحق."),
  HadithEntry(14,"الطريق إلى العلم","مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 2699","صحيح","فضل طلب العلم الشرعي النافع، مع الإخلاص والعمل."),
  HadithEntry(15,"الصدق","عَلَيْكُمْ بِالصِّدْقِ، فَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ.","عبد الله بن مسعود رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 6094؛ مسلم 2607","صحيح","يرشد إلى التزام الصدق في الأقوال والأعمال."),
  HadithEntry(16,"الاستغفار","طُوبَى لِمَنْ وَجَدَ فِي صَحِيفَتِهِ اسْتِغْفَارًا كَثِيرًا.","أبو هريرة رضي الله عنه","سنن ابن ماجه","ابن ماجه 3818","حسن عند عدد من أهل العلم","يشجع على كثرة الاستغفار؛ ينبغي مراجعة تخريج الحديث عند نشره."),
  HadithEntry(17,"العدل","اتَّقُوا الظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ.","جابر رضي الله عنه","صحيح مسلم","مسلم 2578","صحيح","تحذير من الظلم ودعوة إلى أداء الحقوق."),
  HadithEntry(18,"حسن الخلق","أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا.","أبو هريرة رضي الله عنه","سنن أبي داود والترمذي","أبو داود 4682؛ الترمذي 1162","حسن صحيح عند الترمذي","يربط الحديث كمال الإيمان بحسن الخلق في التعامل."),
  HadithEntry(19,"صلاة الفجر والعصر","مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ.","أبو موسى الأشعري رضي الله عنه","صحيح البخاري","البخاري 574","صحيح","المراد صلاتا الفجر والعصر، ويبين الحديث فضل المحافظة عليهما."),
  HadithEntry(20,"إصلاح ذات البين","أَلَا أُخْبِرُكُمْ بِأَفْضَلَ مِنْ دَرَجَةِ الصِّيَامِ وَالصَّلَاةِ وَالصَّدَقَةِ؟ قَالُوا: بَلَى. قَالَ: إِصْلَاحُ ذَاتِ الْبَيْنِ، وَفَسَادُ ذَاتِ الْبَيْنِ الْحَالِقَةُ.","أبو الدرداء رضي الله عنه","سنن أبي داود والترمذي","أبو داود 4919؛ الترمذي 2509","صححه الألباني، وتكلم بعض أهل العلم في إسناده","فيه فضل الإصلاح بين الناس والتحذير من إفساد العلاقات. نُبّه إلى اختلاف أهل العلم في الحكم على إسناده."),

  HadithEntry(21, "الوضوء قبل الصلاة", "لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ.", "أبو هريرة رضي الله عنه", "صحيح مسلم", "مسلم 224", "صحيح", "يبين الحديث ارتباط الصلاة بالطهارة، وتفاصيل الأعذار لها أحكامها."),
  HadithEntry(22,"الطهور من الإيمان","الطُّهُورُ شَطْرُ الإِيمَانِ.","أبو مالك الأشعري رضي الله عنه","صحيح مسلم","مسلم 223","صحيح","فضل الطهارة وأثرها في العبادة."),
  HadithEntry(23,"القرآن حجة","وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ.","أبو مالك الأشعري رضي الله عنه","صحيح مسلم","مسلم 223","صحيح","ينبه إلى أن العلم والعمل بالقرآن مسؤولية، وأن التلاوة ينبغي أن يصاحبها امتثال."),
  HadithEntry(24,"ذكر الله","مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لَا يَذْكُرُ رَبَّهُ مَثَلُ الْحَيِّ وَالْمَيِّتِ.","أبو موسى الأشعري رضي الله عنه","صحيح البخاري","البخاري 6407","صحيح","يحث على دوام ذكر الله تعالى."),
  HadithEntry(25,"دعاء الملكين للمنفق والممسك","مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلَّا مَلَكَانِ يَنْزِلَانِ، فَيَقُولُ أَحَدُهُمَا: اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الْآخَرُ: اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا.","أبو هريرة رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 1442؛ مسلم 1010","صحيح؛ متفق عليه","يبين الحديث فضل الإنفاق في وجوه الخير، ويحذر من الشح ومنع الحقوق. مرجع النص: صحيح مسلم 1010."),
  HadithEntry(26,"فضل السواك","لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ.","أبو هريرة رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 887؛ مسلم 252","صحيح","يبين فضل السواك وحرص النبي على التيسير."),
  HadithEntry(27,"التعاون","الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا.","أبو موسى الأشعري رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 481؛ مسلم 2585","صحيح","يشجع على التعاون والتماسك مع حفظ الحقوق."),
  HadithEntry(28,"الرحمة بالصغير","لَيْسَ مِنَّا مَنْ لَمْ يَرْحَمْ صَغِيرَنَا وَيَعْرِفْ شَرَفَ كَبِيرِنَا.","عبد الله بن عمرو رضي الله عنهما","سنن الترمذي","الترمذي 1919","حسن بحسب الترمذي","يدعو إلى الرحمة بالصغار واحترام الكبار."),
  HadithEntry(29,"الاستئذان","إِنَّمَا جُعِلَ الِاسْتِئْذَانُ مِنْ أَجْلِ الْبَصَرِ.","سهل بن سعد رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 6241؛ مسلم 2156","صحيح","حكمة الاستئذان حفظ خصوصية أهل البيت."),
  HadithEntry(30,"حفظ اللسان","مَنْ يَضْمَنُ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنُ لَهُ الْجَنَّةَ.","سهل بن سعد رضي الله عنه","صحيح البخاري","البخاري 6474","صحيح","يشجع على حفظ اللسان وضبط السلوك؛ يقتصر التطبيق على شرح تربوي مناسب."),


  HadithEntry(31,"فضل قراءة القرآن","اقْرَؤُوا الْقُرْآنَ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لِأَصْحَابِهِ.","أبو أمامة رضي الله عنه","صحيح مسلم","مسلم 804","صحيح","يدعو إلى ملازمة القرآن وتلاوته والعمل به."),
  HadithEntry(32,"تعلم القرآن وتعليمه","خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ.","عثمان رضي الله عنه","صحيح البخاري","البخاري 5027","صحيح","فضل تعلم القرآن وتعليمه بإخلاص."),
  HadithEntry(33,"المداومة على العمل","أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ.","عائشة رضي الله عنها","صحيح البخاري وصحيح مسلم","البخاري 6464؛ مسلم 783","صحيح","الاستمرار على العمل الصالح ولو كان قليلًا."),
  HadithEntry(34,"الدعاء","الدُّعَاءُ هُوَ الْعِبَادَةُ.","النعمان بن بشير رضي الله عنه","سنن الترمذي وأبي داود","الترمذي 2969؛ أبو داود 1479","صححه عدد من أهل العلم","الدعاء عبادة عظيمة، ويحرص المسلم على الإخلاص وحسن الظن بالله."),
  HadithEntry(35,"التوكل والأخذ بالأسباب","لَوْ أَنَّكُمْ كُنْتُمْ تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرُزِقْتُمْ كَمَا تُرْزَقُ الطَّيْرُ، تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا.","عمر بن الخطاب رضي الله عنه","جامع الترمذي","الترمذي 2344","حسن صحيح عند الترمذي","التوكل اعتماد القلب على الله مع السعي والأخذ بالأسباب، وليس ترك العمل. النص وفق جامع الترمذي 2344."),
  HadithEntry(36,"الشكر","عَجَبًا لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ.","صهيب رضي الله عنه","صحيح مسلم","مسلم 2999","صحيح","يذكر الحديث فضل الصبر والشكر في أحوال المؤمن."),
  HadithEntry(37,"إكرام الضيف","مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ.","أبو هريرة رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 6018؛ مسلم 47","صحيح","الإكرام بحسب القدرة دون تكلف أو إسراف."),
  HadithEntry(38,"وصية جبريل بالجار","مَا زَالَ يُوصِينِي جِبْرِيلُ بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ.","عائشة أم المؤمنين رضي الله عنها","صحيح البخاري وصحيح مسلم","البخاري 6014؛ مسلم 2624","صحيح؛ متفق عليه","يؤكد الحديث عظم حق الجار والحث على الإحسان إليه وكف الأذى عنه."),
  HadithEntry(39,"الحياء","الْحَيَاءُ لَا يَأْتِي إِلَّا بِخَيْرٍ.","عمران بن حصين رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 6117؛ مسلم 37","صحيح","الحياء الشرعي خلق يدعو إلى الخير ولا يمنع من طلب العلم."),
  HadithEntry(40,"التواضع","مَنْ تَوَاضَعَ لِلَّهِ رَفَعَهُ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 2588","صحيح","التواضع من الأخلاق التي تحث على احترام الناس."),
  HadithEntry(41,"النية والإخلاص","إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 2564","صحيح","يؤكد الحديث أن الاعتبار بالإيمان والعمل والنية، لا بالمظاهر."),
  HadithEntry(42,"فضل مجالس الذكر","لَا يَقْعُدُ قَوْمٌ يَذْكُرُونَ اللَّهَ عَزَّ وَجَلَّ إِلَّا حَفَّتْهُمُ الْمَلَائِكَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَنَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ.","أبو هريرة وأبو سعيد الخدري رضي الله عنهما","صحيح مسلم","مسلم 2700a-b","صحيح","شهد الصحابيان رضي الله عنهما الحديث عن النبي ﷺ؛ وفيه فضل مجالس ذكر الله. المرجع: صحيح مسلم 2700a-b."),
  HadithEntry(43,"الطريق إلى المسجد","مَنْ غَدَا إِلَى الْمَسْجِدِ أَوْ رَاحَ أَعَدَّ اللَّهُ لَهُ فِي الْجَنَّةِ نُزُلًا.","أبو هريرة رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 662؛ مسلم 669","صحيح","فضل التردد على المساجد للصلاة."),
  HadithEntry(44,"إسباغ الوضوء وكثرة الخطا","أَلَا أَدُلُّكُمْ عَلَى مَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ. قَالَ: إِسْبَاغُ الْوُضُوءِ عَلَى الْمَكَارِهِ، وَكَثْرَةُ الْخُطَا إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ، فَذَلِكُمُ الرِّبَاطُ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 251a","صحيح","يبين الحديث فضل إتمام الوضوء والمشي إلى المساجد وانتظار الصلاة. المرجع: صحيح مسلم 251a."),
  HadithEntry(45,"الصبر","وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ.","أبو سعيد الخدري رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 1469؛ مسلم 1053","صحيح","يبين فضل الصبر وطلبه مع الأخذ بالأسباب."),
  HadithEntry(46,"فرح الله بتوبة عبده","لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا، فَأَتَى شَجَرَةً فَاضْطَجَعَ فِي ظِلِّهَا، قَدْ أَيِسَ مِنْ رَاحِلَتِهِ، فَبَيْنَا هُوَ كَذَلِكَ إِذَا هِيَ بِهَا قَائِمَةٌ عِنْدَهُ، فَأَخَذَ بِخِطَامِهَا، ثُمَّ قَالَ مِنْ شِدَّةِ الْفَرَحِ: اللَّهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ، أَخْطَأَ مِنْ شِدَّةِ الْفَرَحِ.","أنس بن مالك رضي الله عنه","صحيح مسلم","مسلم 2747a","صحيح","يبين الحديث عظيم رحمة الله وفرحه بتوبة عبده. النص والرواية وفق صحيح مسلم 2747a."),
  HadithEntry(47,"التحذير من الغضب","لَا تَغْضَبْ.","أبو هريرة رضي الله عنه","صحيح البخاري","البخاري 6116","صحيح","وصية جامعة بضبط الغضب وتجنب أسباب الأذى."),
  HadithEntry(48,"التكافل","مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ.","عبد الله بن عمر رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 2442؛ مسلم 2699","صحيح","حث على مساعدة الناس وقضاء حاجاتهم."),
  HadithEntry(49,"تفريج الكرب والتيسير وطلب العلم","مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ، وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللَّهِ يَتْلُونَ كِتَابَ اللَّهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ وَغَشِيَتْهُمُ الرَّحْمَةُ وَحَفَّتْهُمُ الْمَلَائِكَةُ وَذَكَرَهُمُ اللَّهُ فِيمَنْ عِنْدَهُ، وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 2699a","صحيح","حديث جامع في تفريج الكرب والتيسير والستر وطلب العلم ومجالس القرآن. المرجع: صحيح مسلم 2699a."),
  HadithEntry(50,"أعمال البر","كُلُّ مَعْرُوفٍ صَدَقَةٌ.","جابر رضي الله عنه","صحيح البخاري","البخاري 6021","صحيح","يشمل المعروف وجوه الخير الممكنة."),
  HadithEntry(51,"المؤمنون كالجسد الواحد","مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ مَثَلُ الْجَسَدِ، إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى.","النعمان بن بشير رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 6011؛ مسلم 2586","صحيح؛ متفق عليه","يضرب النبي ﷺ مثلًا لوحدة المؤمنين في الرحمة والتراحم والتعاون. النص وفق رواية الصحيحين."),
  HadithEntry(52,"محبة النبي ﷺ","لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ.","أنس بن مالك رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 15؛ مسلم 44","صحيح؛ متفق عليه","يدل على وجوب تقديم محبة النبي ﷺ وطاعته على محبة سائر الخلق."),
  HadithEntry(53,"الكلمة الطيبة صدقة","الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ.","أبو هريرة رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 2989؛ مسلم 1009","صحيح؛ متفق عليه","كل قول طيب نافع يدخل في أبواب الصدقة والإحسان."),
  HadithEntry(54,"الرحمة بالناس","مَنْ لَا يَرْحَمُ لَا يُرْحَمُ.","جرير بن عبد الله رضي الله عنه","صحيح البخاري وصحيح مسلم","البخاري 6013؛ مسلم 2319","صحيح؛ متفق عليه","يرشد الحديث إلى الرحمة بالخلق، وأن الجزاء من جنس العمل."),
  HadithEntry(55,"الصلاة على النبي ﷺ","مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 408","صحيح","يبين فضل الصلاة على النبي ﷺ وأن الله يثيب من صلى عليه."),
  HadithEntry(56,"التحذير من الغش","مَنْ غَشَّنَا فَلَيْسَ مِنَّا.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 102","صحيح","تحذير من الغش والخداع في المعاملات وسائر شؤون الناس."),
  HadithEntry(57,"تقوى الله وحسن الخلق","اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ.","أبو ذر الغفاري رضي الله عنه","جامع الترمذي","الترمذي 1987","حسن؛ حسنه الترمذي","يجمع الحديث مراقبة الله، واتباع السيئة بالحسنة، ومعاملة الناس بحسن الخلق."),
  HadithEntry(58,"لا تحتقر المعروف","لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا، وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ.","أبو ذر الغفاري رضي الله عنه","صحيح مسلم","مسلم 2626","صحيح","يدعو إلى عدم الاستهانة بأعمال الخير مهما صغرت، ومنها طلاقة الوجه وحسن اللقاء.")


  ,HadithEntry(59,"خيركم من تعلم القرآن وعلمه","خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ.","عثمان بن عفان رضي الله عنه","صحيح البخاري","البخاري 5027","صحيح","يبين فضل تعلم القرآن وتعليمه، ويشمل ذلك تعلم التلاوة والمعاني والعمل بالهدي."),
  HadithEntry(60,"الإحسان في كل شيء","إِنَّ اللَّهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ.","شداد بن أوس رضي الله عنه","صحيح مسلم","مسلم 1955","صحيح","يدل الحديث على مشروعية الإحسان وإتقان العمل والرفق، في العبادات والمعاملات."),
  HadithEntry(61,"دوام العمل الصالح","أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ.","عائشة رضي الله عنها","صحيح البخاري وصحيح مسلم","البخاري 6464؛ مسلم 783","صحيح؛ متفق عليه","يرشد الحديث إلى المداومة على العمل الصالح ولو كان قليلًا، مع الإخلاص والاستطاعة."),
  HadithEntry(62,"الله في عون العبد","وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 2699","صحيح","فيه فضل قضاء حوائج الناس وإعانتهم، وأن الجزاء من جنس العمل."),
  HadithEntry(63,"شكر الناس","مَنْ لَا يَشْكُرُ النَّاسَ لَا يَشْكُرُ اللَّهَ.","أبو هريرة رضي الله عنه","جامع الترمذي","الترمذي 1954","حسن صحيح عند الترمذي","يرشد إلى الاعتراف بفضل من أحسن إلينا، مع كون الشكر الحقيقي لله تعالى أولًا وآخرًا."),
  HadithEntry(64,"التقوى وحسن الخلق","اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ.","أبو ذر ومعاذ بن جبل رضي الله عنهما","جامع الترمذي","الترمذي 1987","حسن صحيح عند الترمذي","يجمع الحديث وصايا التقوى والتوبة والعمل الصالح وحسن معاملة الناس."),
  HadithEntry(65,"التبسم في وجه المسلم","تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ.","أبو ذر رضي الله عنه","جامع الترمذي","الترمذي 1956","حسن عند الترمذي","يبين أن المعروف لا يقتصر على المال، بل يدخل فيه حسن اللقاء والبشاشة."),
  HadithEntry(66,"كل معروف صدقة","كُلُّ مَعْرُوفٍ صَدَقَةٌ.","جابر بن عبد الله رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 6021؛ مسلم 1005","صحيح؛ متفق عليه","يدخل في الصدقة كل عمل خير نافع، ولو لم يكن إنفاقًا ماليًا."),
  HadithEntry(67,"فضل الصلاة على النبي ﷺ","مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا.","أبو هريرة رضي الله عنه","صحيح مسلم","مسلم 408","صحيح","يبين الحديث فضل الصلاة على النبي ﷺ وعظيم ثوابها."),
  HadithEntry(68,"عدم احتقار المعروف","لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا.","أبو ذر رضي الله عنه","صحيح مسلم","مسلم 2626","صحيح","يدعو الحديث إلى عدم الاستهانة بأي إحسان، ولو كان يسيرًا، وإلى المبادرة للخير."),
  HadithEntry(69,"الأخوة وترك الظلم","الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ.","عبد الله بن عمر رضي الله عنهما","صحيح البخاري وصحيح مسلم","البخاري 2442؛ مسلم 2580","صحيح؛ متفق عليه","يقرر الحديث حقوق الأخوة، ومنها ترك الظلم وعدم التخلي عن المسلم عند حاجته إلى النصرة المشروعة."),
  HadithEntry(70,"الدين يسر","إِنَّ الدِّينَ يُسْرٌ.","أبو هريرة رضي الله عنه","صحيح البخاري","البخاري 39","صحيح","يبين الحديث أن الشريعة مبناها على اليسر المنضبط، ويحذر من الغلو الذي يؤدي إلى الانقطاع.")



)

data class FiqhEntry(
  val id: Int, val title: String, val question: String, val ruling: String,
  val evidence: String, val explanation: String, val scope: String, val references: String
)

val fiqhEntries = listOf(
  FiqhEntry(1,"أصل الوضوء","ما الأعضاء المذكورة في آية الوضوء؟","ذكرت آية الوضوء غسل الوجه واليدين إلى المرافق، ومسح الرأس، وغسل الرجلين إلى الكعبين.","القرآن الكريم، سورة المائدة 5:6.","هذه خلاصة للأعضاء الواردة في الآية، أما صفة الوضوء الكاملة وسننه ونواقضه فتدرس بأدلتها وأقوال أهل العلم.","تعليمي عام؛ لا يتناول تفاصيل الخلاف في بعض جزئيات الصفة.","سورة المائدة: 6؛ صحيح البخاري، كتاب الوضوء."),
  FiqhEntry(2,"الصلاة المفروضة","ما أصل فرض الصلوات المكتوبة؟","الصلاة المكتوبة فريضة على المسلمين، وقد أمر القرآن بالمحافظة عليها وبيّن أن لها أوقاتًا محددة.","القرآن الكريم، سورة النساء 4:103؛ وحديث أركان الإسلام، البخاري 8 ومسلم 16.","يتعلم المسلم أسماء الصلوات وأوقاتها وشروطها وأركانها من مصادر الفقه المعتمدة، ولا تكفي هذه البطاقة وحدها لتعليم صفة الصلاة كاملة.","مدخل عام؛ تفاصيل الأعذار والجمع والقصر لها أبواب مستقلة.","سورة النساء: 103؛ صحيح البخاري 8؛ صحيح مسلم 16."),
  FiqhEntry(3,"التيمم عند العذر","متى يشرع التيمم إجمالًا؟","شرع القرآن التيمم عند فقد الماء أو وجود عذر معتبر يمنع استعماله، ويكون بصعيد طيب مع مسح الوجه واليدين وفق الآية.","القرآن الكريم، سورة المائدة 5:6؛ وسورة النساء 4:43.","للتيمم شروط وتفاصيل تتعلق بالعذر والصعيد والكيفية ونواقضه، وتختلف بعض الجزئيات بين المذاهب؛ فيرجع فيها إلى عالم موثوق.","بيان أصل الحكم فقط؛ لا يقرر جميع صور الأعذار أو تفاصيل المذاهب.","سورة المائدة: 6؛ سورة النساء: 43؛ صحيح البخاري، كتاب التيمم."),
  FiqhEntry(4,"فرض صيام رمضان","ما أصل وجوب صيام رمضان؟","فرض الله صيام شهر رمضان على المؤمنين، وذكر أحكام المريض والمسافر في آيات الصيام.","القرآن الكريم، سورة البقرة 2:183-185.","هذه البطاقة تثبت أصل الفرض ولا تفصل أحكام القضاء والفدية والمرض والسفر والبلوغ؛ فلكل منها شروط وتفصيل فقهي.","مدخل عام؛ الحالات الخاصة تحتاج سؤال أهل العلم مع بيان الحالة.","سورة البقرة: 183-185؛ صحيح البخاري، كتاب الصوم."),
  FiqhEntry(5,"الطهارة للصلاة","ما الدليل على الوضوء للصلاة عند الحدث؟","دلت السنة على أن من أحدث لا يصلي حتى يتوضأ، مع مراعاة أحكام الطهارة وأعذارها.","حديث: لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ؛ صحيح البخاري 135 وصحيح مسلم 225.","الحدث ونواقض الوضوء وأحكام أصحاب الأعذار مسائل لها تفصيل، وهذه البطاقة تذكر أصل الارتباط بين الطهارة والصلاة فقط.","قاعدة عامة؛ لا تستوعب الخلاف في النواقض أو أحوال العذر.","صحيح البخاري 135؛ صحيح مسلم 225؛ سورة المائدة: 6.")  ,
  FiqhEntry(6,"الغسل من الجنابة","ما أصل وجوب الاغتسال من الجنابة؟","أمر القرآن الجنب بالتطهر قبل الصلاة، وتفاصيل صفة الغسل الكاملة تؤخذ من السنة وأبواب الطهارة.","القرآن الكريم، سورة المائدة 5:6؛ وصحيح البخاري، كتاب الغسل.","هذه البطاقة تذكر أصل الحكم ولا تفصل موجبات الغسل أو صفته المجزئة والكاملة أو أحكام الأعذار.","مدخل عام؛ تفاصيل موجبات الغسل وصفته لها أدلة وتفصيل فقهي.","سورة المائدة: 6؛ صحيح البخاري، كتاب الغسل؛ صحيح مسلم، كتاب الحيض."),
  FiqhEntry(7,"استقبال القبلة","ما الأصل في استقبال القبلة عند الصلاة؟","أمر الله نبيه والمؤمنين بالتوجه شطر المسجد الحرام في الصلاة، مع وجود أحكام خاصة بالعجز والخوف والسفر.","القرآن الكريم، سورة البقرة 2:144.","هذه قاعدة عامة، ولا تفصل أحكام العاجز أو من اشتبهت عليه الجهة أو صلاة النافلة على الراحلة.","مدخل عام؛ حالات العجز والسفر لها أحكام خاصة.","سورة البقرة: 144؛ كتب الفقه في باب استقبال القبلة."),
  FiqhEntry(8,"صلاة الجمعة","ما الذي تدل عليه آية الجمعة عند النداء للصلاة؟","أمر القرآن بالسعي إلى ذكر الله وترك البيع عند النداء لصلاة الجمعة، ثم أباح الانتشار بعد قضاء الصلاة.","القرآن الكريم، سورة الجمعة 62:9-10.","شروط وجوب الجمعة وصحتها وأعذار التخلف وعدد المصلين ومسائل الخطبة لها تفصيل فقهي وخلاف معتبر.","لا تستعمل البطاقة وحدها للحكم على حالة شخص بعينه؛ تُراجع شروط الوجوب والعذر.","سورة الجمعة: 9-10؛ كتب الفقه في صلاة الجمعة."),
  FiqhEntry(9,"أصل وجوب الزكاة","ما أصل فرض الزكاة؟","الزكاة فريضة من فرائض الإسلام، وقرن القرآن الأمر بإقام الصلاة بإيتاء الزكاة في مواضع متعددة.","القرآن الكريم، سورة البقرة 2:43؛ وحديث أركان الإسلام، البخاري 8 ومسلم 16.","لا تحدد هذه البطاقة مقدار الزكاة أو النصاب أو الحول؛ فلكل مال زكوي شروط ومقادير وأحكام خاصة.","مدخل عام؛ حساب الزكاة يحتاج معرفة نوع المال وشروطه.","سورة البقرة: 43؛ صحيح البخاري 8؛ صحيح مسلم 16."),
  FiqhEntry(10,"أصل وجوب الحج","ما أصل وجوب الحج؟","فرض الله حج البيت على من استطاع إليه سبيلًا، والاستطاعة لها تفصيل في كتب الفقه.","القرآن الكريم، سورة آل عمران 3:97؛ وحديث أركان الإسلام، البخاري 8 ومسلم 16.","لا تتناول هذه البطاقة تفاصيل المناسك أو النيابة أو الاستطاعة المالية والبدنية؛ يتعلم ذلك من دليل حج موثوق أو معلم مختص.","مدخل عام؛ لا تكفي البطاقة لأداء المناسك دون تعلم صفتها.","سورة آل عمران: 97؛ صحيح البخاري 8؛ صحيح مسلم 16."),

  FiqhEntry(11,"النية في العبادة","هل للنية أثر في العبادة؟","النية معتبرة في العبادات، ويقصد بها العبد العمل لله؛ وتفاصيل محلها وأحكامها يدرسها في أبواب الفقه.","حديث الأعمال بالنيات؛ البخاري 1 ومسلم 1907.","ينبغي التفريق بين النية وبين التلفظ بها، وبين شروط كل عبادة.","قاعدة عامة؛ تفاصيل المذاهب في مواضعها.","البخاري 1؛ مسلم 1907."),
  FiqhEntry(12,"سنن الوضوء","هل توجد أعمال مستحبة في الوضوء؟","وردت صفة الوضوء في السنة، وفيها أعمال مستحبة إلى جانب الأعضاء المفروضة؛ يدرس ترتيبها وأدلتها من كتب الطهارة.","أحاديث صفة وضوء النبي صلى الله عليه وسلم في الصحيحين.","هذه مدخل للمراجعة ولا تحصر السنن أو اختلاف العلماء.","تعليمي؛ يرجع إلى كتب الفقه المعتمدة.","صحيح البخاري وصحيح مسلم، كتاب الوضوء."),
  FiqhEntry(13,"أوقات الصلاة","لماذا يجب تعلم أوقات الصلاة؟","فرضت الصلاة في أوقات محددة، ويجب على المسلم تعلم الوقت وأحكام العذر وفق حاله.","النساء 4:103؛ أحاديث مواقيت الصلاة.","المواقيت قد تختلف باختلاف الموقع، ويستعان بالتقويم الموثوق.","قاعدة عامة؛ مسائل الجمع والعذر لها تفصيل.","النساء: 103؛ كتب الفقه، باب المواقيت."),
  FiqhEntry(14,"آداب المسجد","ما من آداب المسجد؟","من الآداب المحافظة على نظافة المسجد، والسكينة، واحترام المصلين، وعدم التشويش عليهم.","أحاديث النهي عن التشويش على المصلين، وآداب المساجد.","تراعى التعليمات المحلية وآداب المسجد في جميع الأحوال.","آداب عامة؛ تفاصيل أحكام المسجد تراجع في مصادرها.","كتب الحديث والفقه، أبواب المساجد."),
  FiqhEntry(15,"أحكام سجود السهو","لماذا شرع سجود السهو؟","شرع سجود السهو لجبر بعض الخلل في الصلاة بسبب السهو، وتختلف مواضعه بحسب نوع السهو وأدلته.","أحاديث سجود السهو في صحيح البخاري وصحيح مسلم.","لا يكفي هذا الملخص لتحديد سجود السهو في حالة بعينها؛ يلزم معرفة نوع السهو والمذهب أو سؤال أهل العلم.","ملخص تعليمي وليس فتوى شخصية.","صحيح البخاري وصحيح مسلم، أبواب سجود السهو."),
  FiqhEntry(16,"حقوق الجار","ما أصل الإحسان إلى الجار؟","أوصت السنة بالإحسان إلى الجار وترك أذيته، وهو حق يتأكد في المعاملة اليومية.","أحاديث إكرام الجار في الصحيحين.","يتضمن الإحسان حسن المعاملة وكف الأذى والمساعدة بحسب القدرة.","قاعدة أخلاقية وشرعية عامة.","صحيح البخاري وصحيح مسلم، كتاب الأدب."),
  FiqhEntry(17,"آداب الطعام","ما أبرز آداب الطعام الواردة في السنة؟","من الآداب التسمية والأكل باليمين والأكل مما يلي الشخص، بحسب الأحاديث الواردة.","حديث عمر بن أبي سلمة: سم الله وكل بيمينك وكل مما يليك؛ البخاري 5376 ومسلم 2022.","تتعلم الآداب من النصوص مع مراعاة الأعذار.","تعليمي عام.","البخاري 5376؛ مسلم 2022."),
  FiqhEntry(18,"البيع والرضا","ما الأصل في رضا المتبايعين؟","الأصل في المعاملات المشروعة التراضي مع اجتناب الربا والغش والظلم وسائر المحرمات.","النساء 4:29؛ وأحاديث تحريم الغش.","تحتاج تفاصيل العقود إلى دراسة شروطها، ولا يكتفى بهذه القاعدة للحكم على معاملة بعينها.","مدخل عام؛ المعاملات المعاصرة لها تفصيل.","النساء: 29؛ صحيح مسلم 101."),
  FiqhEntry(19,"بر الوالدين","ما حكم الإحسان إلى الوالدين؟","أمر القرآن بالإحسان إلى الوالدين، وقرن ذلك بعبادة الله وحده، مع عدم طاعة المخلوق في معصية الخالق.","الإسراء 17:23-24؛ لقمان 31:14-15.","الإحسان يكون بالقول الكريم والرعاية والاحترام، مع الالتزام بالحق.","قاعدة عامة؛ مسائل خاصة تستفتى فيها جهة علمية.","الإسراء: 23-24؛ لقمان: 14-15."),
  FiqhEntry(20,"الأمانة","ما أهمية حفظ الأمانة؟","أمر الله بأداء الأمانات إلى أهلها، وتشمل الأمانة حقوق الناس ومسؤوليات العبد.","النساء 4:58؛ المؤمنون 23:8.","الأمانة تشمل المال والقول والعمل والمسؤوليات، بحسب ما يقتضيه الحق.","قاعدة عامة.","النساء: 58؛ المؤمنون: 8."),

  FiqhEntry(21,"أحكام صلاة الجماعة","ما فضل صلاة الجماعة؟","شرع الله الصلاة جماعة، ووردت نصوص في فضلها، وتختلف الأحكام التفصيلية بحسب الحال والعذر.","أحاديث فضل الجماعة في الصحيحين.","ينبغي تعلم أحكام الإمام والمأموم والصفوف والاقتداء، وتفصيل الوجوب والخلاف يرجع فيه لأهل العلم.","مدخل تعليمي لا يفصل حكم كل حالة.","صحيح البخاري وصحيح مسلم، أبواب الصلاة."),
  FiqhEntry(22,"أحكام الأذان","ما وظيفة الأذان؟","الأذان إعلان دخول وقت الصلاة ودعوة المسلمين إليها، وله ألفاظ وأحكام تعلم من السنة.","أحاديث الأذان في صحيح البخاري وصحيح مسلم.","يتعلم المتدرب ألفاظ الأذان وأحكام المؤذن والإقامة من مصدر موثوق.","تعليمي؛ لا يغني عن دليل الأذان الكامل.","كتب الفقه والحديث، باب الأذان."),
  FiqhEntry(23,"صلاة الوتر","ما أصل صلاة الوتر؟","الوتر صلاة نافلة مؤكدة وردت صفتها وأوقاتها في السنة، وفي تفاصيلها أوجه معتبرة.","أحاديث الوتر في صحيح البخاري وصحيح مسلم.","تعلم العدد والوقت والصفة من معلم أو كتاب فقهي موثوق.","خلاصة عامة؛ تفاصيل المذاهب تراجع في مصادرها.","كتب الحديث والفقه، باب الوتر."),
  FiqhEntry(24,"صلاة الضحى","ما صلاة الضحى؟","صلاة الضحى نافلة وردت أحاديث في فضلها وأدائها في وقت الضحى.","أحاديث صلاة الضحى في صحيح مسلم وغيرها.","تعلم وقتها وعدد ركعاتها من مصادر السنة.","مدخل عام.","كتب الحديث والفقه، باب صلاة الضحى."),
  FiqhEntry(25,"الاعتكاف","ما أصل الاعتكاف؟","الاعتكاف عبادة ورد ذكرها في القرآن والسنة، وتعلم شروطها وأحكامها من كتب الفقه.","البقرة 2:187؛ أحاديث اعتكاف النبي صلى الله عليه وسلم.","تختلف بعض التفاصيل الفقهية في الشروط والمدة وأحكام المعتكف.","مدخل عام لا يحكم على حالة معينة.","البقرة: 187؛ صحيح البخاري، كتاب الاعتكاف."),
  FiqhEntry(26,"صدقة التطوع","ما فضل الصدقة؟","حثت النصوص على الصدقة والإحسان، مع مراعاة الحقوق والواجبات والنية.","آيات الصدقة وأحاديثها في الصحيحين.","تقدم الحقوق الواجبة، ويستحب التطوع بحسب القدرة.","مدخل عام.","القرآن؛ صحيح البخاري وصحيح مسلم، أبواب الزكاة."),
  FiqhEntry(27,"آداب الصيام","ما بعض آداب الصائم؟","من آداب الصيام حفظ اللسان، وترك الأذى، والإكثار من العمل الصالح.","أحاديث الصيام في صحيح البخاري.","هذه الآداب لا تحصر جميع أحكام الصيام ولا تفصل الأعذار.","مدخل عام.","صحيح البخاري، كتاب الصوم."),
  FiqhEntry(28,"الحقوق المالية","كيف يحفظ المسلم حقوق الناس المالية؟","يجب حفظ الحقوق وأداء الديون والأمانات، ويحرم الغش والاعتداء على المال.","النساء 4:58؛ النساء 4:29؛ أحاديث الحقوق.","تحتاج النزاعات والعقود إلى تفصيل ومراجعة مختص.","قاعدة عامة وليست فتوى في نزاع.","القرآن الكريم؛ كتب الفقه، أبواب المعاملات."),
  FiqhEntry(29,"الغيبة","ما الغيبة؟","الغيبة ذكر الإنسان بما يكره في غيبته، وقد نهى القرآن عنها.","الحجرات 49:12؛ حديث الغيبة في صحيح مسلم.","يتعلم المسلم حفظ اللسان والابتعاد عن نقل الكلام، مع أحكام استثناءات شرعية تدرس من مصادرها.","مدخل تربوي؛ الاستثناءات تحتاج علمًا.","الحجرات: 12؛ صحيح مسلم 2589."),
  FiqhEntry(30,"التوبة","ما شروط التوبة إجمالًا؟","التوبة رجوع إلى الله من المعصية، وتشتمل إجمالًا على الإقلاع والندم والعزم على عدم العودة، ورد الحقوق إذا تعلق الأمر بحقوق الناس.","آيات التوبة وأحاديثها الصحيحة.","تُراجع تفاصيل التوبة من أهل العلم، ولا يأس من رحمة الله.","مدخل عام؛ تفاصيل حقوق العباد لها أحكام.","القرآن الكريم؛ صحيح مسلم، كتاب التوبة."),


  FiqhEntry(31,"تحريم الغش","ما أصل تحريم الغش؟","الغش والخداع في المعاملة محرمان، ويجب بيان العيوب المؤثرة وعدم خداع الناس.","حديث من غشنا فليس منا؛ صحيح مسلم 102.","تتعدد صور الغش في البيع والاختبارات والعمل، ويرجع في الحالات التفصيلية إلى أهل العلم.","مدخل عام.","صحيح مسلم 102؛ كتب الفقه."),
  FiqhEntry(32,"الوفاء بالعقود","ما الأصل في الوفاء بالعقود؟","أمر الله المؤمنين بالوفاء بالعقود والعهود المشروعة.","المائدة 5:1.","تُستثنى العقود المحرمة، وتفصيل الشروط يرجع لأهل الاختصاص.","قاعدة عامة.","سورة المائدة: 1."),
  FiqhEntry(33,"تحريم الربا","ما أصل تحريم الربا؟","حرم الله الربا وأمر بتركه، وتفصيل أنواعه وأحكام المعاملات يرجع إلى مصادر الفقه.","البقرة 2:275-279.","لا يصدر الحكم على عقد مالي بعينه دون فهم شروطه وتفاصيله.","مدخل عام.","سورة البقرة: 275-279."),
  FiqhEntry(34,"اليمين","ما أهمية حفظ اليمين؟","حث الشرع على حفظ الأيمان، ولليمين أحكام في الانعقاد والحنث والكفارة.","المائدة 5:89.","تفاصيل أنواع الأيمان والكفارة تحتاج دراسة أو سؤال أهل العلم.","مدخل عام.","سورة المائدة: 89."),
  FiqhEntry(35,"الوصية","ما الأصل في الوصية؟","وردت أحكام الوصية في القرآن والسنة، وتراعى فيها حقوق الورثة والحدود الشرعية.","البقرة 2:180؛ أحاديث الوصية.","الوصايا المالية تحتاج مراجعة مختص بسبب شروطها وحقوق الورثة.","مدخل عام.","القرآن الكريم؛ كتب الفرائض والوصايا."),
  FiqhEntry(36,"العدل في الشهادة","ما واجب المسلم في الشهادة؟","أمر القرآن بالعدل في الشهادة وعدم كتمانها أو تحريفها.","البقرة 2:283؛ النساء 4:135.","الشهادة مسؤولية، وتراعى شروطها وإجراءاتها.","قاعدة عامة.","البقرة: 283؛ النساء: 135."),
  FiqhEntry(37,"الصلح","ما فضل الصلح بين الناس؟","الصلح مشروع لإزالة النزاع مع حفظ الحقوق وعدم تحليل الحرام أو تحريم الحلال.","النساء 4:128؛ الحجرات 49:9-10.","تختلف أحكام الصلح باختلاف النزاع والحقوق.","مدخل عام.","النساء: 128؛ الحجرات: 9-10."),
  FiqhEntry(38,"الوقف","ما معنى الوقف؟","الوقف من صور الصدقة الجارية في الفقه، وتعلم شروطه وأحكامه من مصادر معتبرة.","حديث إذا مات ابن آدم انقطع عمله إلا من ثلاث؛ مسلم 1631.","تفاصيل إنشاء الوقف وإدارته تتطلب مراعاة القواعد الشرعية والنظامية.","مدخل عام.","صحيح مسلم 1631؛ كتب الفقه."),
  FiqhEntry(39,"حقوق الطريق","ما بعض حقوق الطريق؟","من حقوق الطريق كف الأذى وغض البصر ورد السلام وإرشاد الناس بحسب النصوص.","حديث حقوق الطريق؛ صحيح البخاري وصحيح مسلم.","تراعى السلامة والأنظمة العامة.","مدخل عام.","صحيح البخاري وصحيح مسلم، أبواب الأدب."),
  FiqhEntry(40,"الستر وعدم التجسس","ما أصل النهي عن التجسس؟","نهى القرآن عن التجسس وسوء الظن والغيبة، وأمر بحفظ كرامة الناس.","الحجرات 49:12.","يستثنى ما تدعو إليه ضرورة معتبرة وفق أحكامها، ولا يتوسع في انتهاك الخصوصية.","مدخل عام.","الحجرات: 12."),
 
  FiqhEntry(41,"النية في العبادة","ما أهمية النية؟","النية محلها القلب، ويحتاج العمل إلى قصد معتبر بحسب العبادة.","حديث الأعمال بالنيات؛ البخاري 1 ومسلم 1907.","لا يلزم التلفظ بالنية في كل عبادة؛ تفاصيل المسائل تراجع في كتب الفقه.","قاعدة عامة.","البخاري 1؛ مسلم 1907."),
  FiqhEntry(42,"سنن الفطرة","ما معنى سنن الفطرة؟","تدل النصوص على خصال النظافة والفطرة، ومنها السواك وقص الأظافر ونحوها.","صحيح مسلم 257.","تختلف الأحكام التفصيلية في بعض الخصال ومددها.","مدخل عام.","صحيح مسلم، كتاب الطهارة."),
  FiqhEntry(43,"صلاة الجماعة","ما فضل صلاة الجماعة؟","وردت النصوص في فضل صلاة الجماعة، مع أحكام تختلف بحسب حال المكلف.","البخاري 645؛ مسلم 650.","الحكم التفصيلي و الأعذار فيه يرجع إلى أهل العلم.","مدخل عام.","صحيح البخاري وصحيح مسلم."),
  FiqhEntry(44,"الجمعة","ما أصل صلاة الجمعة؟","صلاة الجمعة شعيرة واجبة على من تحققت فيه شروطها الشرعية.","الجمعة 62:9؛ أحاديث الجمعة.","تراعى شروط الوجوب والأعذار وأحكام السفر.","مدخل عام.","القرآن؛ كتب الفقه."),
  FiqhEntry(45,"صلاة الوتر","ما حكم الوتر؟","الوتر صلاة مؤكدة في السنة، وللعلماء تفصيل في حكمها.","أحاديث الوتر في الصحيحين والسنن.","عدد الركعات وصفتها ووقتها لها تفاصيل متعددة.","مدخل عام.","كتب الحديث والفقه."),
  FiqhEntry(46,"زكاة الفطر","ما مقصد زكاة الفطر؟","شرعت زكاة الفطر في نهاية رمضان، ولها مقدار ووقت وأحكام.","أحاديث زكاة الفطر؛ البخاري ومسلم.","تفاصيل المقدار والتوقيت والأصناف محل مراجعة فقهية.","مدخل عام.","الصحيحان؛ كتب الفقه."),
  FiqhEntry(47,"البيع والرضا","ما أصل التراضي في البيع؟","أصل المعاملات المالية التراضي مع اجتناب المحرمات والغرر والظلم.","النساء 4:29؛ أحاديث البيوع.","العقود المعاصرة تحتاج دراسة شروطها وتفاصيلها.","قاعدة عامة.","النساء: 29؛ كتب البيوع."),
  FiqhEntry(48,"اليمين","ما حكم اليمين؟","تشرع اليمين بالله ولا يجوز الحلف كذبًا، وتترتب أحكام الكفارة في بعض الحالات.","المائدة 5:89.","تفاصيل اليمين والحنث والكفارة بحسب الواقعة.","مدخل عام.","المائدة: 89."),
  FiqhEntry(49,"الغيبة","ما تعريف الغيبة؟","نهى القرآن عن الغيبة، وهي ذكر الإنسان بما يكره مما فيه.","الحجرات 49:12؛ حديث مسلم 2589.","توجد حالات استثناء ذكرها أهل العلم بضوابط، لا يجوز التوسع فيها.","مدخل عام.","الحجرات: 12؛ مسلم 2589."),
  FiqhEntry(50,"آداب الدعاء","ما آداب الدعاء؟","يدعو المسلم بإخلاص وحضور قلب، ويجتنب الاعتداء في الدعاء.","الأعراف 7:55؛ أحاديث الدعاء.","الأدعية المأثورة أولى، ولا يحدد التطبيق أعدادًا غير ثابتة.","مدخل عام.","الأعراف: 55؛ كتب الأذكار."),
  FiqhEntry(51,"صلاة الجمعة","ما أصل وجوب صلاة الجمعة؟","أمر الله بالسعي إلى ذكر الله عند النداء لصلاة الجمعة وترك البيع وقتها، وتفاصيل شروط الوجوب والصحة تدرس في كتب الفقه.","القرآن الكريم، سورة الجمعة 62:9-10.","هذه بطاقة تعريفية؛ شروط الجمعة وأعذار تركها وعدد الجماعة وبعض تفاصيلها مسائل فقهية يرجع فيها إلى أهل العلم.","لا تقدم البطاقة فتوى لحالة فردية أو تفصيلًا لجميع المذاهب.","سورة الجمعة: 9-10؛ كتب الفقه في باب صلاة الجمعة."),
  FiqhEntry(52,"بر الوالدين","ما منزلة بر الوالدين؟","قرن القرآن الأمر بالإحسان إلى الوالدين بعبادة الله وحده، وأمر بالقول الكريم وخفض الجناح لهما.","القرآن الكريم، سورة الإسراء 17:23-24؛ سورة لقمان 31:14.","البر يكون بالقول الطيب والإحسان والطاعة في المعروف، ولا طاعة لمخلوق في معصية الخالق.","تراعى أحوال الأسرة والحقوق المتبادلة، وتعرض المشكلات الخاصة على أهل العلم المختصين.","الإسراء: 23-24؛ لقمان: 14-15."),
  FiqhEntry(53,"صلة الرحم","ما أصل صلة الرحم؟","أمر الشرع بصلة الأرحام وحذر من قطيعتها، وتكون الصلة بحسب الاستطاعة والعرف والحاجة.","القرآن الكريم، سورة النساء 4:1؛ وصحيح البخاري 5984 وصحيح مسلم 2556.","تتنوع الصلة بين الزيارة والسؤال والمساعدة والكلمة الطيبة، ويراعى في ذلك دفع الضرر والقدرة.","تختلف صور الصلة باختلاف القرب والحال والعرف، ولا تحصر في وسيلة واحدة.","النساء: 1؛ البخاري 5984؛ مسلم 2556."),
  FiqhEntry(54,"حقوق الجار","ما حق الجار في الإسلام؟","حثت النصوص على الإحسان إلى الجار وكف الأذى عنه، سواء كان قريبًا أو غير قريب.","النساء 4:36؛ صحيح البخاري 6014 وصحيح مسلم 2624.","من الإحسان تفقد الجار، ومساعدته، واحترام خصوصيته، وعدم إيذائه بالقول أو الفعل.","تراعى الحقوق والأنظمة والعرف، ولا يجوز التعدي باسم الجوار.","النساء: 36؛ البخاري 6014؛ مسلم 2624."),
  FiqhEntry(55,"الصدقة والتطوع","ما الفرق العام بين الزكاة والصدقة التطوعية؟","الزكاة عبادة مالية مفروضة بشروط وأنصبة ومصارف محددة، أما الصدقة التطوعية فباب واسع من الإحسان.","التوبة 9:60؛ البقرة 2:261؛ صحيح البخاري 1395.","لا تغني الصدقة التطوعية عن الزكاة الواجبة إذا وجبت، وتفاصيل الحساب والمصارف تحتاج إلى معرفة المال والحال.","هذه خلاصة تعليمية ولا تحسب مقدار زكاة شخص بعينه.","التوبة: 60؛ البقرة: 261؛ كتب الزكاة."),
  FiqhEntry(56,"تحريم الربا","ما أصل تحريم الربا؟","حرم الله الربا وأمر بترك ما بقي منه، وبيّن الفرق بين البيع والربا.","القرآن الكريم، سورة البقرة 2:275-279؛ آل عمران 3:130.","تطبيق الحكم على المنتجات والعقود المالية المعاصرة يحتاج إلى فحص شروط العقد وسؤال جهة علمية موثوقة.","لا تصنف البطاقة عقدًا مصرفيًا بعينه دون دراسة تفاصيله.","البقرة: 275-279؛ آل عمران: 130؛ كتب فقه المعاملات."),
  FiqhEntry(57,"آداب الاستئذان","ما أدب دخول البيوت؟","أمر القرآن بالاستئذان والسلام قبل دخول بيوت الآخرين، حفظًا للخصوصية وصيانة للحقوق.","القرآن الكريم، سورة النور 24:27-28.","ينتظر المستأذن الإذن، ويرجع إذا طلب منه الرجوع، ولا يتطلع إلى داخل البيت.","تراعى أحكام البيوت والعلاقات الأسرية والخصوصية.","النور: 27-28؛ كتب الآداب."),
  FiqhEntry(58,"الوفاء بالعقود","ما أصل الوفاء بالعقود والعهود؟","أمر الله المؤمنين بالوفاء بالعقود، ونهى عن أكل أموال الناس بالباطل.","القرآن الكريم، سورة المائدة 5:1؛ النساء 4:29.","يلتزم المسلم بالشروط المشروعة، أما الشرط المحرم أو النزاع في عقد معين فيحتاج إلى مراجعة مختص.","قاعدة عامة لا تغني عن دراسة العقد ونوعه وشروطه.","المائدة: 1؛ النساء: 29؛ كتب المعاملات."),
  FiqhEntry(59,"تحريم الظلم","ما حكم الظلم في الإسلام؟","حرم الشرع الظلم وأمر بأداء الحقوق، ويشمل ظلم النفس والناس والتعدي على الأموال والأعراض.","القرآن الكريم، سورة الشورى 42:42؛ صحيح مسلم 2577.","يجب رد الحقوق والتوبة وطلب المسامحة حيث يلزم، وتفاصيل رد المظالم تتعلق بنوع الحق والواقعة.","هذه قاعدة عامة وليست حكمًا قضائيًا في نزاع محدد.","الشورى: 42؛ صحيح مسلم 2577."),
  FiqhEntry(60,"الأمانة والوفاء","ما أصل أداء الأمانات؟","أمر الله بأداء الأمانات إلى أهلها وبالحكم بالعدل، ونهى عن خيانة الأمانة.","القرآن الكريم، سورة النساء 4:58؛ الأنفال 8:27.","تشمل الأمانة الودائع والحقوق والمسؤوليات والكلام والعهود، ويجب ردها إلى أصحابها.","تختلف تفاصيل الضمان عند التلف أو التقصير بحسب الواقعة والفقه المعتمد.","النساء: 58؛ الأنفال: 27؛ كتب الفقه والآداب.")


)

data class QuranStory(
  val id: Int, val title: String, val summary: String, val verses: String,
  val lessons: List<String>, val sourceNote: String,
  val chapters: List<String> = emptyList()
)

val quranStories = listOf(
  QuranStory(1,"قصة يوسف عليه السلام","يعرض القرآن رؤيا يوسف، ومحنته مع إخوته، وانتقاله إلى مصر، وابتلاءه في السجن، ثم تمكين الله له واجتماع أسرته.","سورة يوسف: 4-101.",listOf("الصبر عند الشدائد","العفة والأمانة","العفو عند المقدرة","حسن الظن بتدبير الله"),"الملخص مستخرج من تسلسل الآيات؛ لا تضاف تفاصيل القصاص والروايات غير المذكورة في القرآن إلا بعد تخريجها.",listOf(
    "الفصل الأول: الرؤيا وبداية الابتلاء\\nتبدأ القصة برؤيا رآها يوسف عليه السلام، ورؤيا الأنبياء وحي، وقد قصها على أبيه يعقوب عليهما السلام. أدرك يعقوب أن لهذه الرؤيا شأنًا، فنصح ابنه ألا يقصها على إخوته حتى لا يحملهم الحسد على الكيد له. وفي هذا الموقف تظهر عناية الأب بابنه، كما يظهر أن النعمة قد تكون موضع ابتلاء، وأن الحكمة تقتضي كتمان بعض الأمور عن من لا يأمن المرء حسده. لم تكن الرؤيا نهاية الطريق ولا إعلانًا عن تحقق الأمر فورًا؛ بل كانت بداية مسار طويل من الابتلاءات. ويعلمنا هذا المطلع أن وعد الله حق، لكن تحقق آثاره يكون في الوقت الذي يشاؤه الله، وأن المؤمن يجمع بين حسن الظن بالله والحذر المشروع. كما يبين أن الأبوة الصالحة ليست عاطفة فقط، بل توجيه وتعليم وتنبيه إلى العواقب. المرجع: يوسف 4-6.",
    "الفصل الثاني: كيد الإخوة وإلقاء يوسف في الجب\\nتذكر السورة ما وقع في نفوس إخوة يوسف من الغيرة، وكيف اجتمعوا على إبعاده عن أبيه. وتعرض الآيات تدبيرهم ثم تنفيذهم ما عزموا عليه، وعودتهم إلى أبيهم بقميص يوسف وعذرهم الذي لم يكن صادقًا. لم يذكر القرآن كل تفصيل جزئي في الرحلة أو المكان، ولذلك لا يصح أن نملأ الفراغات بحكايات لا تثبت. المهم الذي تقرره الآيات أن يوسف تعرض لظلم شديد من أقرب الناس إليه، وأن الله لم يتركه في محنته. ويظهر في موقف يعقوب صبر جميل، أي صبر لا يصحبه اعتراض على قضاء الله ولا يأس من رحمته. إن وقوع الظلم من قريب لا يبيح مقابلة الظلم بالظلم، كما أن الحزن لا ينافي الصبر؛ فقد حزن يعقوب واشتد وجده، لكنه بقي متعلقًا بالله. المرجع: يوسف 7-18.",
    "الفصل الثالث: النجاة والانتقال إلى مصر\\nتنتقل القصة من الجب إلى مرحلة جديدة، إذ جاءت سيارة فأرسلوا واردهم، فوجد يوسف وأخرجوه، ثم بيع بثمن قليل. وهكذا انتقل من محنة إلى واقع جديد لا يعرف ما يخفيه له المستقبل. وتخبر السورة أن الذي اشتراه في مصر أكرم مثواه، وأن الله مكن ليوسف في الأرض وعلمه من تأويل الأحاديث. هنا يلفت القرآن النظر إلى تدبير الله الذي قد تجري أسبابه في صورة لا يتوقعها الإنسان؛ فالخروج من الجب لم يكن نهاية الابتلاء، لكنه كان طريقًا إلى مرحلة أخرى من التمكين والتربية. ومن الدروس أن الإنسان لا يحكم على حياته من مشهد واحد، فقد يكره أمرًا ويكون في عاقبته خير لا يعلمه. كما أن التمكين لا ينفصل عن العلم والحكمة، ولذلك جمع الله في الآيات بين التمكين وتعليم يوسف. المرجع: يوسف 19-22.",
    "الفصل الرابع: الثبات أمام الفتنة\\nتذكر السورة ابتلاء يوسف في بيت العزيز، حين راودته امرأة العزيز عن نفسه، فاستعاذ بالله وامتنع عن المعصية. وتعرض الآيات القرائن التي أظهرت براءته، ثم ما تبع ذلك من انتشار الخبر وحديث النسوة. لم يساوم يوسف على طاعة الله مع أنه كان غريبًا بعيدًا عن أهله، وفي موضع قد تضعف فيه رقابة الناس؛ لكنه استحضر مراقبة الله. وهذا من أعظم معاني العفة: أن يختار المرء رضا الله ولو خالف هواه، وأن يبتعد عن أسباب الحرام ولا يتذرع بالظروف. كما تبين القصة أن البراءة قد تحتاج إلى ظهور الدليل، وأن الاتهام لا يجعل البريء مذنبًا. وقد دعا يوسف ربه أن يصرف عنه كيدهن، وفي ذلك تعليم للمؤمن أن يستعين بالله وألا يغتر بقوته وحدها. المرجع: يوسف 23-35.",
    "الفصل الخامس: السجن والدعوة إلى الله\\nدخل يوسف السجن مع أنه بريء، وكان هذا ابتلاء آخر بعد ابتلاء الجب والفتنة. لكن السجن لم يمنعه من الإحسان إلى من حوله، ولا من الدعوة إلى توحيد الله. حين سأله الفتيان عن تأويل رؤياهما، لم يبدأ بتقديم العلم مجردًا عن غايته، بل دعا إلى عبادة الله وحده وبيّن بطلان الشرك، ثم أجابهما بما علمه الله. ويظهر هنا أن صاحب الرسالة يستطيع أن يكون نافعًا في أحلك الظروف، وأن الدعوة ليست مرتبطة بالراحة أو المكانة. كما تعلمنا الآيات حسن اختيار الوقت والأسلوب، والبدء بالأصل الأعظم وهو توحيد الله. وبعد أن أوّل الرؤيا طلب من الذي ظن أنه ناجٍ أن يذكره عند الملك، لكن الشيطان أنساه ذكره، فلبث يوسف في السجن بضع سنين. المرجع: يوسف 36-42.",
    "الفصل السادس: رؤيا الملك وظهور البراءة\\nرأى الملك رؤيا عجز الملأ عن تأويلها، فتذكر الناجي يوسف بعد مدة، وذهب إليه يسأله. ففسر يوسف الرؤيا بسنوات الخصب التي يعقبها الجدب، ولم يكتف بالتأويل، بل قدم خطة واضحة لحفظ المحصول والتعامل مع سنوات الشدة. في ذلك دليل على أن العلم النافع يجمع بين الفهم والعمل، وأن التخطيط والأخذ بالأسباب من تمام التوكل. ثم لم يخرج يوسف مباشرة قبل أن تظهر براءته؛ فسأل عن شأن النسوة، وأقررن بما علمن من براءته. لم يكن طلبه للبراءة طلب شهرة أو انتقام، بل حتى لا يخرج والاتهام باقٍ يلاحقه. وهنا يظهر خلق الأناة والحرص على وضوح الحق، وأن المنصب لا ينبغي أن يطلب لمجرد الجاه، بل قد يطلبه الإنسان إذا كان قادرًا على أداء الأمانة وتحقيق المصلحة. المرجع: يوسف 43-57.",
    "الفصل السابع: خزائن الأرض وتحمل المسؤولية\\nبعد ظهور براءة يوسف، قربه الملك وجعله ذا مكانة، فطلب يوسف أن يجعله على خزائن الأرض، وذكر أنه حفيظ عليم. لم يكن ذلك تزكية متكبرة للنفس، بل بيانًا لما يحتاج إليه العمل من حفظ وعلم، مع قيامه بما يصلح للناس. وتوضح السورة أن الله مكن ليوسف في الأرض يتبوأ منها حيث يشاء، وأن رحمته تصيب من يشاء ولا يضيع أجر المحسنين. وتعلمنا هذه المرحلة أن الكفاءة والأمانة صفتان أساسيتان في تحمل المسؤوليات، وأن صاحب العلم لا يخفي قدرته إذا توقف عليها نفع عام، بشرط الصدق والتواضع. كما أن النجاح لا ينبغي أن يقطع صاحبه عن ربه؛ فالتمكين فضل من الله واختبار في كيفية استعمال النعمة. المرجع: يوسف 54-57.",
    "الفصل الثامن: لقاء الإخوة وامتحان المواقف\\nتذكر الآيات مجيء إخوة يوسف إلى مصر لطلب الميرة، فعرفهم يوسف وهم له منكرون. وجرت أحداث متتابعة في السورة قادت إلى عودة الإخوة ثم رجوعهم مرة أخرى، وطلبهم إحضار أخيهم، ثم احتباس أخيه عنده وفق التدبير الذي أذن الله به. لا ينبغي أن نضيف إلى هذه الأحداث تفاصيل حوارية من الخيال أو نجزم بأسماء لم يذكرها القرآن. وتبرز هذه المرحلة كيف تغيرت الأحوال؛ فالإخوة الذين ظلموا يوسف صاروا في موضع حاجة إليه، لكنه لم يعجل بالانتقام. كما يظهر أثر الصبر الطويل في قلب يعقوب، إذ لم يقطع رجاءه من الله رغم امتداد الفراق. ومن الدروس أن القدرة على رد الإساءة لا تعني أن الانتقام هو الخيار الأفضل، وأن الحكمة قد تقتضي التدرج حتى تنكشف الحقائق وتصلح النفوس. المرجع: يوسف 58-87.",
    "الفصل التاسع: انكشاف الحقيقة والعفو\\nاشتد الأمر على إخوة يوسف، فعادوا إليه يطلبون المساعدة، فعرفهم بنفسه وذكّرهم بما فعلوا. عندها اعترفوا بخطئهم، وأقروا بفضل الله عليه. وكان جوابه إعلان العفو: لا تثريب عليهم، مع الدعاء لهم بالمغفرة. هذا الموقف من أعظم مشاهد العفو عند المقدرة؛ فقد صار يوسف في موضع قوة، وكان قادرًا على المؤاخذة، لكنه اختار الصفح والإحسان. والعفو هنا لا يعني أن الظلم كان أمرًا حسنًا، ولا أن الحقوق لا قيمة لها، بل يعني أن صاحب الحق قد يختار الصفح ابتغاء ما عند الله وإصلاحًا للعلاقة. ثم أرسل قميصه إلى أبيه، فارتد بصيرًا واجتمع شمل الأسرة. وتظهر الآيات صدق وعد الله، وأن الفرج قد يأتي بعد طول انتظار. المرجع: يوسف 88-98.",
    "الفصل العاشر: رجوع الإخوة إلى أبيهم وما كشفه الصبر\\nبعد أن بقي بنيامين في مصر، رجع الإخوة إلى أبيهم يحملون خبرًا جديدًا يزيده حزنًا، لكن يعقوب عليه السلام لم يجعل المصيبة سببًا لليأس. تذكر الآيات أنه قال: فصبر جميل، ثم وجّه أبناءه إلى البحث عن يوسف وأخيه، ونهاهم عن القنوط من روح الله. وهذا التوجيه يعلّم أن الصبر ليس استسلامًا ولا تركًا للأسباب؛ فقد جمع يعقوب بين التفويض إلى الله والعمل والبحث. كما أن تكرار البلاء لا يقطع صلة المؤمن بربه، بل قد يزيده افتقارًا ودعاءً. وفي القصة تربية على ألا نحكم على خاتمة أمرٍ من منتصف الطريق، فقد تتوالى الأحداث الصعبة بينما لا نعلم ما يقدره الله بعدها. المرجع: يوسف 83-87.",
    "الفصل الحادي عشر: أدب الرجاء عند اشتداد الحاجة\\nعاد إخوة يوسف إلى مصر في حال شدة، ووصفوا ما أصابهم وأهلهم من الضر، وطلبوا المساعدة. لم تجعلهم حاجتهم يملكون كل الإجابات، لكنها دفعتهم إلى التواضع وطلب المعروف. وفي هذا المشهد تتغير لغة الحوار؛ فبعد مواقف القوة والجدال صاروا يعترفون بالحاجة، ويطلبون الوفاء والإحسان. ويُفهم من السياق أن الشدة قد تكشف للإنسان ضعفه وتدعوه إلى مراجعة نفسه، وأن طلب العون ليس عيبًا إذا كان بأدب وصدق. كما يظهر فضل الإحسان إلى المحتاج، خصوصًا إذا كان بينه وبين المحسن تاريخ من الخلاف؛ فصاحب الخلق الكريم لا يجعل الماضي حاجزًا يمنعه من فعل الخير. المرجع: يوسف 88.",
    "الفصل الثاني عشر: لحظة التعريف وظهور الحقيقة\\nحين رأى يوسف أن الوقت قد حان لكشف الأمر، واجه إخوته بالحقيقة وسألهم عن فعلهم القديم، ثم عرّفهم بنفسه. كانت لحظة فاصلة في القصة؛ فالأشخاص الذين ظنوا أن أمرهم انتهى منذ زمن وجدوا أنفسهم أمام من ظلموه، وقد صار في موضع قدرة. لم ينسب يوسف الفضل إلى ذكائه وحده، بل قال إن الله منّ عليه، فربط النعمة بواهبها. وهذا أدب عظيم عند النجاح: أن يتذكر الإنسان فضل الله وألا يتكبر على من حوله. كما أن الاعتراف بالحقيقة بداية إصلاح، فالخطأ لا يُعالج بإنكاره، بل بالصدق والندم وطلب العفو ورد الحقوق بحسب القدرة. المرجع: يوسف 89-91.",
    "الفصل الثالث عشر: العفو الذي يفتح باب الإصلاح\\nأقر الإخوة بخطئهم، وظهر ندمهم، فاختار يوسف عليه السلام العفو وقال لهم إنه لا تثريب عليهم في ذلك اليوم، ودعا الله أن يغفر لهم. لم يكن العفو إنكارًا لما حدث، ولم يجعل الظلم صوابًا، لكنه قرار كريم صدر ممن امتلك القدرة على المؤاخذة. ومن المهم أن نفهم أن العفو فضيلة حين يكون فيه خير، وأن حفظ الحقوق وطلب الإنصاف مشروعان أيضًا؛ فليس كل موقف يلزم صاحبه أن يتنازل عن حقه. وتكشف القصة أن القوة الحقيقية ليست في التشفي، بل في ضبط النفس واختيار ما يصلح. كما تعلمنا أن الاعتذار الصادق ينبغي أن يتبعه إصلاح عملي، وأن العلاقات قد تُبنى من جديد إذا اجتمع الاعتراف بالخطأ مع الصفح والحكمة. المرجع: يوسف 92.",
    "الفصل الرابع عشر: قميص يوسف وبشارة اللقاء\\nأرسل يوسف قميصه مع إخوته إلى أبيه، وأمرهم أن يلقوه على وجهه، فارتد بصيرًا بإذن الله. ثم تحركت الأسرة نحو اللقاء بعد طول فراق. يعرض القرآن هذه الأحداث بإيجاز مؤثر، ولا يذكر تفاصيل الطريق أو كل ما دار بين أفراد الأسرة؛ لذلك يلتزم هذا العرض بما ثبت في الآيات ولا يضيف حوارات متخيلة. وفي هذه المرحلة نرى كيف عاد الرجاء بعد أن طال الانتظار، وكيف صار الخبر الذي حمله الأبناء سببًا لتجدد الأمل. ومن الدروس أن الكلمة الطيبة والبشارة الصادقة قد تخففان عن الناس، وأن نقل الأخبار يحتاج إلى أمانة، فلا يضيف المرء إليها ما لم يعلمه. المرجع: يوسف 93-98.",
    "الفصل الخامس عشر: تمام النعمة والعبرة من القصة\\nاجتمع يوسف بأبويه ورفع أبويه على العرش وخروا له سجدًا، وكانت تلك تحية معروفة في شريعتهم، وليست سجود عبادة؛ فالسجود عبادة لا تكون إلا لله في شريعتنا. وتحققت الرؤيا التي قصها يوسف على أبيه في بداية القصة. ثم توجه يوسف إلى ربه شاكرًا أن آتاه من الملك وعلمه من تأويل الأحاديث، وسأله أن يتوفاه مسلمًا ويلحقه بالصالحين. وختمت السورة ببيان أن في قصص الأنبياء عبرة لأولي الألباب، وأنها ليست حديثًا مفترى. ومن مجموع القصة نتعلم الصبر عند الشدة، والعفة عند الفتنة، والإحسان في موضع القدرة، وحسن التدبير، والثقة بوعد الله. ولا تختصر القصة في أن كل مظلوم سيحصل على منصب دنيوي؛ بل معناها الأعمق أن العاقبة لله، وأن المؤمن يثبت على الحق في كل مرحلة، سواء رأى الثمرة عاجلًا أم لم يرها. المرجع: يوسف 99-111.",
  )),
  QuranStory(2,"قصة نوح عليه السلام","يذكر القرآن دعوة نوح لقومه، وإصراره على دعوتهم، وموقف المكذبين، ثم أمر الله بصنع الفلك ونجاة المؤمنين.","سورة هود: 25-49؛ وانظر سورة نوح: 1-28.",listOf("الصبر في الدعوة","التوكل على الله","أن النجاة بالإيمان لا بمجرد القرابة","العبرة بعاقبة التكذيب"),"يعتمد العرض على الآيات المحددة، مع تجنب تحديد أمور لم يحددها النص القرآني.",listOf(
    "الفصل الأول: بدء الرسالة والإنذار\\nأرسل الله نوحًا عليه السلام إلى قومه يدعوهم إلى عبادة الله وحده وينذرهم من عذاب يوم أليم. بدأ دعوته ببيان واضح: أن يعبدوا الله ويتقوه ويطيعوا رسوله، ووعدهم أن الاستجابة سبب للمغفرة والإمهال إلى أجل معلوم. يبين هذا المطلع أن دعوة الأنبياء تقوم على التوحيد، وأن الناصح يريد لقومه الخير والنجاة لا مجرد الغلبة عليهم. المرجع: هود 25-26؛ نوح 1-4.",
    "الفصل الثاني: تنوع أساليب الدعوة والصبر عليها\\nذكر نوح عليه السلام أنه دعا قومه ليلًا ونهارًا، وأعلن لهم دعوته وجهر بها وأسرها، فلم يزدهم ذلك إلا فرارًا. وتعرض سورة نوح تكرار دعوته لهم إلى الاستغفار، وتذكيرهم بنعم الله في خلق السماوات والأرض وإنزال المطر. تكشف الآيات طول مدة الدعوة وتنوع أساليبها، وتعلم الداعية الصبر والرفق والوضوح، وألا ييأس لمجرد قلة المستجيبين. المرجع: نوح 5-20.",
    "الفصل الثالث: موقف الملأ والمكذبين\\nاعترض الملأ من قوم نوح على رسالته، واحتجوا بأنه بشر مثلهم وأن الذين اتبعوه ضعفاء في نظرهم. فأجابهم نوح بأن أتباعه ليسوا موضع احتقار، وأن حسابهم على الله، وأنه لا يطرد المؤمنين طلبًا لرضا المتكبرين. يظهر في هذا الحوار أن قيمة الإنسان ليست بالمال أو المكانة، وأن الداعية لا يبيع الحق لإرضاء أصحاب النفوذ. المرجع: هود 27-31.",
    "الفصل الرابع: استمرار الجدال وإقامة الحجة\\nواصل نوح دعوته وبيّن لقومه أنه لا يملك خزائن الله ولا يعلم الغيب ولا يدعي لنفسه مقامًا ليس له، وإنما هو رسول يبلغ ما أمره الله به. ورد على استعجالهم العذاب بأن أمره إلى الله، وأنه لا يستطيع دفع حكمه عنهم. في ذلك درس في صدق الأنبياء وتواضعهم، وأن الرسول لا يتكلم من عند نفسه في أمر الوحي. المرجع: هود 31-35.",
    "الفصل الخامس: الأمر بصنع الفلك\\nأوحى الله إلى نوح أنه لن يؤمن من قومه إلا من قد آمن، وأمره أن يصنع الفلك بعين الله ووحيه، وألا يراجعه في شأن الظالمين. أخذ نوح ينفذ أمر ربه، وكلما مر عليه ملأ من قومه سخروا منه، فذكرهم أنه سيعلمون من يأتيه عذاب يخزيه. لا يذكر القرآن تفاصيل صناعة السفينة وأدواتها، فلا تضاف إليها أوصاف جازمة بلا دليل. المرجع: هود 36-39.",
    "الفصل السادس: ركوب السفينة وموقف الابن\\nجاء أمر الله وفار التنور، فأمر نوح أن يحمل في الفلك من كل زوجين اثنين وأهله ومن آمن، إلا من سبق عليه القول. وذكر القرآن حوار نوح مع ابنه الذي أبى الركوب وظن أن الجبل يعصمه من الماء، فبيّن له نوح أنه لا عاصم اليوم من أمر الله إلا من رحم. وانتهى الحوار بحيلولة الموج بينهما. وتقرر الآيات أن النجاة ليست بمجرد النسب، بل بالإيمان ورحمة الله. المرجع: هود 40-43.",
    "الفصل السابع: انتهاء الطوفان والنجاة\\nقضي الأمر واستوت السفينة على الجودي، وقيل للأرض أن تبلعي ماءك وللسماء أن تقلعي، وغيض الماء، ثم جاء خطاب الله لنوح بما يقرر العدل والرحمة. وبعد ذلك ذكر القرآن نجاة نوح ومن معه، وأمره بالهبوط بسلام وبركات. تعرض الآيات نهاية مرحلة طويلة من الصبر والابتلاء، وتؤكد أن تدبير الكون كله بيد الله. المرجع: هود 44-48.",
    "الفصل الثامن: الدعاء والعبرة من القصة\\nتضمنت سورة نوح دعاءه لربه وذكره حاله مع قومه، وختمت بدعائه للمؤمنين والمؤمنات، كما تضمنت سورة هود توجيه الله له حين سأل ما ليس له به علم، فاستغفر وأناب. ومن أعظم الدروس أن العاطفة لا تقدم على حكم الله، وأن المؤمن يرجع إلى ربه إذا تبين له وجه الصواب. كما نتعلم أن طول الطريق لا يبرر ترك الدعوة، وأن العاقبة لله، وأن النجاة بالإيمان والعمل الصالح ورحمة الله. المرجع: هود 45-49؛ نوح 26-28."
    "الفصل التاسع: دعوة نوح في السر والعلن\\nتصف سورة نوح تنوع الوسائل التي استخدمها نبي الله في دعوة قومه؛ فذكر أنه دعاهم ليلًا ونهارًا، ثم أعلن لهم وجهر وأسر. وهذا التنوع يدل على حرصه على إيصال الحق، وعلى أن الداعية ينظر في أحوال من يخاطبهم ويختار الأسلوب المناسب من غير أن يغيّر أصل الرسالة. لم تكن المشكلة في غموض الدعوة، فقد كان أصلها واضحًا: عبادة الله والاستغفار والتوبة، لكن القوم قابلوا البيان بالإعراض. نتعلم من ذلك أن نجاح الإنسان لا يقاس دائمًا بسرعة استجابة الآخرين، وأن واجبه بذل السبب بأمانة وصبر، أما هداية القلوب فبيد الله وحده. المرجع: نوح 5-9.",
    "الفصل العاشر: الاستغفار وأثره في حياة الناس\\nكرر نوح عليه السلام دعوة قومه إلى الاستغفار، وذكر لهم ما يترتب عليه من مغفرة الله وإنزال المطر والإمداد بالأموال والبنين وجعل الجنات والأنهار. لا تعرض الآيات الاستغفار كعبارة تقال باللسان مع الإصرار على الإعراض، بل تأتي في سياق دعوة إلى الرجوع إلى الله وترك الكفر. ومن الخطأ تحويل هذه الآيات إلى وعد آلي بأن كل من استغفر سيحصل فورًا على مال أو ولد؛ فالأرزاق والحكمة بيد الله، والآيات تبين فضل التوبة وآثار الطاعة في الجملة. ويستفيد القارئ أن يكثر من الاستغفار مع صدق التوبة وإصلاح العمل، وأن لا يجعل العبادة مجرد وسيلة لمصلحة دنيوية. المرجع: نوح 10-12.",
    "الفصل الحادي عشر: التفكر في خلق الله\\nانتقل نوح في خطابه إلى تذكير قومه بآيات الله في أنفسهم وفي الكون؛ فسألهم كيف لا يرجون لله وقارًا، وذكر خلقهم أطوارًا، وخلق السماوات، وجعل القمر نورًا والشمس سراجًا، وإنبات الأرض. هذا الاستدلال يوقظ العقل من الغفلة، ويبين أن التأمل في الخلق يقود إلى معرفة عظمة الخالق، لا إلى الغرور بالعلم أو القوة. وفي زمننا يستطيع المسلم أن يتأمل انتظام الكون ودقة خلقه، مع العلم أن الآيات لم تنزل لتكون كتابًا في تفاصيل العلوم التجريبية، بل لتدل على قدرة الله وتدعو إلى عبادته. المرجع: نوح 13-20.",
    "الفصل الثاني عشر: خطر التقليد واتباع المتكبرين\\nذكرت سورة نوح أن قومًا أصروا على اتباع رموزهم وأصنامهم، وأن ذلك كان سببًا في زيادة الضلال. ويظهر من سياق الدعوة أن الإنسان قد يرفض الحق لا لضعف الدليل، بل لأنه ألف طريقًا ووجد من يزينه له. لذلك لا يصح أن يجعل المسلم كثرة الأتباع معيارًا للصواب، ولا أن يتبع شخصًا في كل شيء دون معرفة الدليل. وفي المقابل، لا يعني ذلك سوء الظن بكل عالم أو قائد؛ بل الواجب احترام أهل العلم مع فهم أن العصمة للأنبياء فيما يبلغونه عن الله. وتعلمنا القصة أن العادة والمكانة الاجتماعية لا تحول الباطل إلى حق، وأن النجاة تكون باتباع الهدى. المرجع: نوح 21-24.",
    "الفصل الثالث عشر: القرابة لا تغني عن الإيمان\\nمن أكثر مواضع قصة نوح تأثيرًا حواره مع ابنه حين دعاه إلى الركوب في السفينة، فرفض الابن واعتمد على الجبل، فبيّن له نوح أنه لا عاصم من أمر الله إلا من رحم. ثم حال الموج بينهما. وبعد ذلك سأل نوح ربه عن ابنه، فجاءه التوجيه الإلهي أن الأمر متعلق بالعمل الصالح، وأن ما خفي عنه لا ينبغي أن يسأل عنه بغير علم. تكشف هذه الآيات أن محبة الوالد لولده لا تغير ميزان الحق، وأن القرابة لا تقوم مقام الإيمان. كما تعلمنا أن الإنسان قد يحب شخصًا ويتمنى له الخير، لكنه لا يملك هدايته، وأن على الوالدين النصح والرحمة والدعاء مع إدراك حدود مسؤوليتهم. المرجع: هود 42-46.",
    "الفصل الرابع عشر: الرجوع إلى الله عند الخطأ\\nحين سأل نوح عليه السلام ربه في شأن ابنه، علّمه الله أن يسأله ما ليس له به علم، فاستعاذ نوح بالله أن يكون من الجاهلين، وسأله المغفرة والرحمة. وهذا الموقف يعلّمنا أن مقام النبوة لا يعني أن العبد يستغني عن توجيه ربه، وأن الرجوع إلى الحق فضيلة لا نقص. إذا ظهر للإنسان أن سؤاله أو حكمه لم يكن على علم كافٍ، فليتوقف وليستغفر وليتعلم، بدل المكابرة والدفاع عن الخطأ. وفيه أيضًا أدب الدعاء؛ فالمؤمن يسأل الله ما ينفعه، ويتأدب مع علمه وحكمته، ولا يعترض على حكمه بسبب عاطفة أو رغبة شخصية. المرجع: هود 45-47.",
    "الفصل الخامس عشر: ميراث الصبر والثبات\\nتختم قصة نوح في هذه المواضع بدروس تتجاوز زمنها: الثبات على التوحيد، والصبر في الدعوة، والرفق في البيان، وعدم الاغترار بالكثرة أو المكانة، والتوبة عند ظهور الخطأ، والتسليم لحكمة الله. كما تذكرنا القصة أن نوحًا دعا قومه زمنًا طويلًا كما ورد في القرآن، وأن قلة المستجيبين لا تعني أن الدعوة فشلت؛ فالمعيار هو القيام بما أمر الله به. ولا يجوز أن ننسب إلى القصة تفاصيل عن شكل السفينة أو عدد من ركبها أو أسماء لم يذكرها الوحي على وجه الجزم. نقرأ القصة لنتعلم الهداية التي دلت عليها الآيات، ونرجع إلى القرآن عند اختلاف الروايات. المرجع: نوح 1-28؛ هود 25-49."
  )),
  QuranStory(3,"قصة إبراهيم عليه السلام وتحطيم الأصنام","يحاور إبراهيم قومه في عبادة الأصنام، ويقيم عليهم الحجة، ثم يواجه موقفهم بعد تحطيم الأصنام وينجيه الله من كيدهم.","سورة الأنبياء: 51-70؛ وانظر سورة الأنعام: 74-83.",listOf("إفراد الله بالعبادة","التفكر والاستدلال","الثبات على الحق","التوكل على الله"),"تسلسل القصة مأخوذ من القرآن الكريم؛ لا تُضاف حوارات أو تفاصيل تاريخية غير موثقة.",listOf(
    "الفصل الأول: الرشد الذي آتاه الله لإبراهيم\\nيخبرنا القرآن أن الله آتى إبراهيم رشده من قبل، وأنه كان به عليمًا. فالقصة تبدأ ببيان أن الهداية فضل من الله، وأن إبراهيم عليه السلام لم يكن تابعًا للأوهام السائدة في قومه. والرشد يشمل وضوح الحق وحسن اتباعه، ولذلك واجه إبراهيم قومه بالحجة ولم يكتف بمخالفتهم في قلبه. نتعلم أن طلب الحق يحتاج إلى عقل متأمل وقلب منصف، وأن الإنسان لا يجعل العادة أو كثرة الناس بديلًا عن الدليل. المرجع: الأنبياء 51.",
    "الفصل الثاني: سؤال الأب بأدب ووضوح\\nعرض القرآن حوار إبراهيم مع أبيه، إذ سأله عن تماثيل يتخذونها آلهة، وبيّن له أنه يراه وقومه في ضلال مبين. وفي موضع آخر ذكر حواره معه ودعوته إياه إلى ترك عبادة ما لا يسمع ولا يبصر ولا يغني عنه شيئًا. يظهر في هذا الخطاب اجتماع وضوح العقيدة مع الأدب في الحديث؛ فلم يكن إبراهيم غامضًا في إنكار الشرك، ولم يجعل الدعوة مبررًا للفحش أو التكبر. المرجع: مريم 41-48؛ الأنعام 74.",
    "الفصل الثالث: التأمل في ملكوت السماوات والأرض\\nتذكر سورة الأنعام نظر إبراهيم في الكوكب ثم القمر ثم الشمس، وإعلانه براءته من الآلهة التي تأفل، وتوجيه وجهه للذي فطر السماوات والأرض. يعرض القرآن هذا الاستدلال لإظهار بطلان عبادة ما يغيب ويتغير، وأن الإله الحق لا يكون مخلوقًا محتاجًا. ينبغي فهم الآيات في سياق احتجاج إبراهيم على قومه، لا تحويلها إلى حكاية عن شك في الله؛ فقد ذكر القرآن أنه آتاه رشده من قبل. المرجع: الأنعام 75-79.",
    "الفصل الرابع: إعلان التوحيد بلا مواربة\\nبعد أن أقام إبراهيم الحجة، أعلن توحيده لله وحده وبراءته مما يشركون. وهذا الإعلان يبين أن التوحيد ليس فكرة ذهنية فحسب، بل موقف يحدد العبادة والولاء والعمل. كما يعلّمنا أن المسلم يزن المعتقدات بالدليل، وأنه لا يخلط بين احترام الأشخاص وبين موافقتهم على الخطأ. كان إبراهيم يخاطب قومًا لهم عادات راسخة، ومع ذلك لم يجعل ضغط المجتمع سببًا لترك الحق. المرجع: الأنعام 78-82.",
    "الفصل الخامس: مواجهة عبادة الأصنام بالحجة\\nسأل إبراهيم قومه عن هذه التماثيل التي هم لها عاكفون، فلفت أنظارهم إلى أنهم وآباءهم كانوا في ضلال مبين. لم يكن السؤال مجرد استنكار، بل دعوة إلى التفكير: ما الذي يجعل شيئًا مصنوعًا بأيدي البشر مستحقًا للعبادة؟ ويكشف هذا الحوار أن التقليد وحده لا يكفي لإثبات العقائد، وأن على الإنسان أن يتدبر ما ورثه وأن يعرضه على الوحي والعقل السليم. المرجع: الأنبياء 52-54.",
    "الفصل السادس: جواب القوم ورفضهم مراجعة الموروث\\nأجاب القوم بأنهم وجدوا آباءهم لها عابدين، فظهر اعتمادهم على التقليد بدل تقديم البرهان. ورد إبراهيم بأنه جاءهم بالحق وأن ربهم رب السماوات والأرض الذي فطرهن. في هذا الموقف فرق واضح بين الاحتجاج بالدليل والاحتجاج بمجرد أن السابقين فعلوا ذلك. لا يعني هذا التقليل من شأن الآباء أو التراث الصحيح، وإنما يعني أن عبادة الله لا تثبت بعادة بشرية، وأن الحق أحق بالاتباع مهما كان عمر العادة وانتشارها. المرجع: الأنبياء 54-56.",
    "الفصل السابع: موقف إبراهيم من الأصنام\\nيذكر القرآن أن إبراهيم قال إنه سيكيد أصنامهم بعد أن يولوا مدبرين، ثم جعل الأصنام جذاذًا إلا كبيرًا لهم لعلهم إليه يرجعون. لا يسرد القرآن تفاصيل الأدوات أو المكان أو كيفية التنفيذ، ولذلك لا يصح الجزم بتفاصيل لم يذكرها. المقصود في سياق الآيات إظهار عجز ما يعبدونه، وتهيئة القوم لمواجهة السؤال الذي يكشف تناقض اعتقادهم. وينبغي للقارئ أن يميز بين نص القرآن وبين القصص المتداولة التي قد تزيد أحداثًا لا تثبت. المرجع: الأنبياء 57-58.",
    "الفصل الثامن: سؤالهم عن الفاعل\\nلما رجع القوم ورأوا أصنامهم محطمة، تساءلوا عمن فعل ذلك، وذكر بعضهم إبراهيم لأنه كان يتكلم عن آلهتهم. استدعوه وسألوه، فصار الموقف فرصة لعرض الحجة أمامهم. ويظهر هنا أن إبراهيم لم يكن هدفه صناعة مشهد غامض، بل كشف عجز الأصنام أمام أصحابها. فلو كانت تملك نفعًا أو دفعًا لكان لها من القدرة ما تدافع به عن نفسها، وهذا هو موضع التأمل الذي قادت إليه الأحداث. المرجع: الأنبياء 59-62.",
    "الفصل التاسع: الحجة التي أعادت السؤال إليهم\\nجاء جواب إبراهيم: بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون. يذكر القرآن أن القوم رجعوا إلى أنفسهم فقالوا إنهم هم الظالمون، ثم نكسوا على رؤوسهم. ويشرح أهل التفسير هذا الموضع في سياق إلزامهم بما يقرون به من عجز الأصنام؛ فهي لا تنطق ولا تجيب. لا ينبغي اقتطاع الجملة من سياق المناظرة أو تحويلها إلى قاعدة تبيح الكذب؛ فالمقام مقام احتجاج يكشف فساد عبادتهم. المرجع: الأنبياء 63-65.",
    "الفصل العاشر: اعترافهم بعجز ما يعبدون\\nقالوا لإبراهيم إنه يعلم أن هذه الأصنام لا تنطق، فجاء السؤال الذي يوقظ الفطرة: أفتعبدون من دون الله ما لا ينفعكم شيئًا ولا يضركم؟ هنا تتضح الحجة؛ فالمعبود الذي لا يملك لنفسه جوابًا ولا نفعًا ولا ضرًا لا يستحق العبادة. ومن الدروس أن الإيمان لا يقوم على الانفعال وحده، بل على معرفة من نعبد ولماذا نعبده، وأن التفكر الصادق قد يجعل المرء يعترف بتناقض كان يغفل عنه. المرجع: الأنبياء 65-67.",
    "الفصل الحادي عشر: الثبات أمام قرار القوم\\nبدل أن يقبل القوم الحجة، انتقلوا إلى التهديد والعقوبة، وقالوا حرقوه وانصروا آلهتكم إن كنتم فاعلين. وهذا يبين أن وضوح الدليل لا يعني أن كل مخالف سيقبل الحق فورًا؛ فقد تدفع العصبية بعض الناس إلى رد الحجة بالقوة. نتعلم من ذلك أن الحوار يحتاج إلى صبر، وأن رفض الآخرين لا يجعل الباطل حقًا، وأن صاحب المبدأ يثبت على الحق مع التزام الحكمة وتجنب العدوان. المرجع: الأنبياء 68.",
    "الفصل الثاني عشر: أمر الله فوق كيد البشر\\nقال الله للنار أن تكون بردًا وسلامًا على إبراهيم، فكانت نجاته بقدرة الله. يركز القرآن على المعجزة نفسها ولا يطلب منا تخيل تفاصيل لا نص عليها. وهذه الآية تعلم المؤمن أن الأسباب كلها تحت مشيئة الله، وأنه سبحانه ينصر من يشاء بالطريقة التي يشاء. ولا تعني القصة أن الإنسان يعرّض نفسه للخطر اعتمادًا على وقوع معجزة؛ فالمعجزات آيات خاصة يؤيد الله بها رسله، وليست تعليمات لتقليد مواقفها. المرجع: الأنبياء 69.",
    "الفصل الثالث عشر: بطلان كيد المعتدين\\nأراد القوم بإبراهيم كيدًا، فجعلهم الله الأخسرين، ونجاه ومن معه إلى الأرض التي بارك فيها للعالمين. تبرز الآيات أن القوة الظاهرة لا تضمن لصاحبها النصر إذا استعملها في الباطل، وأن العاقبة ليست دائمًا لمن يملك العدد أو السلطة. كما أن النجاة منحة من الله، وليست دليلًا على أن طريق الحق خالٍ من الابتلاء. وفي حياة المسلم يكون الثبات مقرونًا بالصبر والأخذ بالأسباب المشروعة، مع تفويض النتائج إلى الله. المرجع: الأنبياء 70-71.",
    "الفصل الرابع عشر: أثر التوحيد في بناء الشخصية\\nتجمع قصة إبراهيم بين التفكر والشجاعة الأدبية والأدب مع الوالد والوضوح في العقيدة. فهو لم يتبع قومه لمجرد أنهم أكثر عددًا، ولم يترك السؤال حين رأى أن الموروث يحتاج إلى برهان، ولم يجعل الخلاف سببًا لترك البيان. وهذه معانٍ يحتاج إليها طالب العلم: أن يسأل بأدب، ويتثبت من الدليل، ويقبل الحق إذا ظهر، ولا يتعصب لرأي لمجرد أنه اعتاده. كما تذكرنا القصة بأن التوحيد أصل الرسالات، وأن العبادة حق لله وحده. المرجع: الأنعام 74-83؛ الأنبياء 51-71.",
    "الفصل الخامس عشر: خلاصة القصة ومصادر تدبرها\\nقصة إبراهيم عليه السلام ليست مجرد مواجهة مع تماثيل، بل دعوة إلى تحرير القلب والعقل من عبادة غير الله، وإلى النظر في دلائل الخلق، والثبات على الحق مع حسن الخطاب. والآيات التي ينبغي الرجوع إليها عند قراءة القصة هي سورة الأنبياء من الآية 51 إلى 71، وسورة الأنعام من الآية 74 إلى 83، مع مواضع الحوار في سورة مريم. وقد تعمد هذا العرض الاقتصار على ما تدل عليه الآيات، والتنبيه إلى المواضع التي لا يذكر القرآن تفاصيلها. ومن أراد مزيدًا من البيان فليرجع إلى كتب التفسير المعتمدة. المرجع: الأنبياء 51-71؛ الأنعام 74-83؛ مريم 41-48."
  )),
  QuranStory(4,"قصة موسى عليه السلام","تتناول الآيات نداء الله لموسى، وإرساله إلى فرعون، وآياته، ومواجهة السحرة، وما جرى لبني إسرائيل في مقاطع متعددة من السورة.","سورة طه: 9-98؛ وتوجد مقاطع أخرى في سور القصص والأعراف والشعراء.",listOf("الثقة بالله عند التكليف","مواجهة الظلم بالحجة","أن النصر من عند الله","أهمية الصبر والذكر"),"هذه نسخة تعليمية موسعة من مقاطع القصة، وليست استيعابًا لكل ما ورد عن موسى عليه السلام في القرآن.",listOf(
    "الفصل الأول: نشأة موسى في زمن الخوف\\nتذكر سورة القصص أن فرعون علا في الأرض وجعل أهلها شيعًا يستضعف طائفة منهم، يذبح أبناءهم ويستحيي نساءهم. وفي هذا الجو شاء الله أن يحفظ موسى عليه السلام، فأوحى إلى أمه أن ترضعه، فإذا خافت عليه ألقتْه في اليم ولا تخاف ولا تحزن، ووعدها أن يرده إليها ويجعله من المرسلين. تكشف الآيات أن تدبير الله نافذ حتى في أشد الظروف، وأن الخوف لا يمنع المؤمن من الأخذ بالأسباب والطاعة. المرجع: القصص 4-7.",
    "الفصل الثاني: عودة موسى إلى أمه\\nالتقط آل فرعون موسى، وجعل الله امرأة فرعون تقول إنه قرة عين لها وله، ورُد موسى إلى أمه كي تقر عينها ولا تحزن. لا يذكر القرآن تفاصيل كثيرة عن طفولته، ولذلك لا ينبغي إضافة حكايات جازمة من غير سند. لكن الآيات تبين كيف اجتمع حفظ الله مع أسباب ظاهرة؛ فقد حُفظ الطفل في بيت من كان يهدد قومه، ثم عاد إلى أمه. وفي ذلك معنى عظيم: قد يهيئ الله الفرج من جهة لا يتوقعها الإنسان. المرجع: القصص 8-13.",
    "الفصل الثالث: بلوغ موسى ومغادرته مصر\\nلما بلغ موسى أشده واستوى آتاه الله حكمًا وعلمًا، ثم وقع منه ما ذكرته الآيات حين وجد رجلين يقتتلان، فاستغاثه أحدهما، فوكز الآخر فقضى عليه. فاستغفر موسى ربه واعترف بخطئه، فغفر الله له. ثم جاءه خبر التآمر عليه، فخرج من المدينة خائفًا يترقب ودعا ربه أن ينجيه من القوم الظالمين. نتعلم أن الاعتراف بالخطأ والرجوع إلى الله من صفات الصالحين، وأن القوة لا تعفي من المسؤولية. المرجع: القصص 14-21.",
    "الفصل الرابع: الوصول إلى مدين ومساعدة المحتاج\\nتوجه موسى إلى مدين، ولما ورد ماءها وجد أمة من الناس يسقون ووجد من دونهم امرأتين تذودان، فسألهما عن شأنهما ثم سقى لهما. وبعد ذلك تولى إلى الظل ودعا ربه أن ينزل إليه من خيره. يظهر في الموقف خلق المبادرة إلى المعروف من غير انتظار مقابل، مع حفظ الأدب والحياء. كما يبين أن الإنسان إذا نزلت به حاجة فليدع الله وليعمل بما يستطيع، ولا يجعل حاجته سببًا لترك المروءة أو التعدي على حقوق الآخرين. المرجع: القصص 22-24.",
    "الفصل الخامس: العمل والوفاء بالعهد\\nجاءت إحدى المرأتين إلى موسى تمشي على استحياء، ودعته إلى أبيها ليجزيه أجر ما سقى لهما. ثم جرى الاتفاق على أن يعمل عنده مدة معلومة، وذكر القرآن إتمام موسى للأجل. لا يحدد النص اسم الرجل ولا تفاصيل الحياة اليومية، فلا نجزم بما لم يرد. وتعلمنا الآيات قيمة العمل الحلال والوفاء بالعهد، وأن الاتفاقات ينبغي أن تكون واضحة، وأن الأمانة والقوة من الصفات التي يُحتاج إليها في العمل. المرجع: القصص 25-28.",
    "الفصل السادس: النداء عند الطور\\nلما قضى موسى الأجل وسار بأهله آنس من جانب الطور نارًا، فقال لأهله امكثوا إني آنست نارًا لعلي آتيكم منها بخبر أو جذوة من النار. فلما أتاها نودي من جانب الوادي المبارك، وأخبره الله أنه سبحانه رب العالمين. وفي سورة طه جاء تفصيل النداء والأمر بخلع النعلين، وأن الله اختاره واستمع لما يوحى. هذا المشهد يبين عظمة الوحي وأن الرسالة اصطفاء من الله، لا منصب يطلبه الإنسان لنفسه. المرجع: القصص 29-30؛ طه 9-14.",
    "الفصل السابع: التكليف والاعتماد على الله\\nأمر الله موسى أن يذهب إلى فرعون، فذكر موسى حاجته إلى شرح صدره وتيسير أمره وحل عقدة من لسانه، وطلب أن يجعل له وزيرًا من أهله، هارون أخاه، يشد أزره ويشاركه في الأمر. فاستجاب الله دعاءه. نتعلم أن التوكل لا يعني إخفاء الحاجة أو ترك طلب العون المشروع؛ فقد سأل موسى ربه التيسير والاستعانة بأخيه، ثم مضى في المهمة. كما أن القائد الناجح يعرف أهمية التعاون وتقسيم المسؤوليات. المرجع: طه 25-36.",
    "الفصل الثامن: خطاب فرعون بالحكمة\\nأمر الله موسى وهارون أن يذهبا إلى فرعون وأن يقولا له قولًا لينًا لعله يتذكر أو يخشى. وهذا أصل مهم في الدعوة: لين العبارة لا يعني التنازل عن الحق، بل يجمع بين وضوح الرسالة وحسن الأسلوب. وقد أُمر موسى أن يبلّغ فرعون أنهما رسولا رب العالمين وأن يرسل معهما بني إسرائيل ولا يعذبهم. وتبين القصة أن الدعوة إلى الحق لا تبرر السب أو الإهانة، وأن مخاطبة المخالف بالحكمة لا تمنع من بيان الظلم وطلب رفعه. المرجع: طه 43-48؛ الشعراء 16-17.",
    "الفصل التاسع: آيات الله وموقف السحرة\\nأظهر الله لموسى آياته، ومنها العصا واليد، لتكونا برهانًا على صدق رسالته. جمع فرعون السحرة لمواجهة موسى، فلما ألقوا حبالهم وعصيهم خُيّل إلى الناس من سحرهم أنها تسعى، فألقى موسى عصاه فإذا هي تلقف ما يأفكون. عندها عرف السحرة أن ما جاء به موسى ليس من جنس السحر، فآمنوا برب العالمين. تبرز هذه المرحلة أن معرفة الحق قد تغير موقف الإنسان في لحظة، وأن أصحاب الخبرة قد يدركون الفرق بين الخداع والآية. المرجع: طه 56-73؛ الأعراف 109-126.",
    "الفصل العاشر: ثبات السحرة بعد الإيمان\\nلما آمن السحرة توعدهم فرعون، لكنهم أعلنوا أنهم لن يؤثروا طاعته على ما جاءهم من البينات، وسألوا الله المغفرة والثبات. كان انتقالهم من طلب الأجر إلى الإيمان موقفًا عظيمًا؛ إذ قدموا الحق على المصلحة والتهديد. ولا تعرض الآيات هذا الثبات على أنه أمر سهل، بل تبين أن الإيمان قد يقتضي تحمل تبعات الموقف. ومن الدروس ألا يجعل المرء رضا الناس أو خوفه منهم ميزانًا للحق، وأن يسأل الله الثبات إذا عرف الصواب. المرجع: طه 70-73؛ الشعراء 46-51.",
    "الفصل الحادي عشر: خروج بني إسرائيل ليلًا\\nاستمر فرعون في العناد، وأوحى الله إلى موسى أن يسري بعباده، فاتبعهم فرعون وجنوده. وعندما تراءى الجمعان قال أصحاب موسى إنا لمدركون، فقال موسى كلا إن معي ربي سيهدين. يظهر هنا أثر الثقة بالله عند اشتداد الأسباب الظاهرة؛ فالمؤمن لا ينهار أمام الخطر، ولا ينسب النجاة إلى قوته وحدها. كما تعلمنا الآيات أن الظلم قد يطول، لكن لا يخرج عن علم الله وقدرته، وأن على المظلوم أن يسعى إلى النجاة بالطرق المشروعة ويستعين بالله. المرجع: الشعراء 52-62.",
    "الفصل الثاني عشر: انفلاق البحر والنجاة\\nأوحى الله إلى موسى أن يضرب البحر بعصاه، فانفلق فكان كل فرق كالطود العظيم، ونجى الله موسى ومن معه وأغرق فرعون وجنوده. القرآن يذكر الحدث آية من آيات الله، ولا يطلب من القارئ إضافة تفاصيل تخمينية عن شكل الطريق أو زمن العبور. وتؤكد القصة أن النصر من عند الله، وأن الطغيان لا يحمي صاحبه مهما بلغت قوته. كما تذكرنا بأن النجاة تستوجب الشكر، وأن من رأى آيات الله ينبغي أن يزداد إيمانًا وطاعة لا غرورًا. المرجع: الشعراء 63-68؛ طه 77-79.",
    "الفصل الثالث عشر: نعمة الله على بني إسرائيل\\nذكّر الله بني إسرائيل بما أنجاهم به من عدوهم، وما واعد موسى، وما رزقهم من الطيبات، وأمرهم بألا يطغوا فيه فيحل عليهم غضبه. وهذا يبين أن النجاة ليست نهاية المسؤولية؛ فالنعمة تحتاج إلى شكر واستقامة. وقد ينجو الإنسان من شدة ثم ينسى المنعم إذا لم يجدد ذكره لله. لذلك ينبغي أن تتحول النعم إلى طاعة، وأن لا يستعملها المرء في المعصية أو الظلم. المرجع: طه 80-82.",
    "الفصل الرابع عشر: فتنة العجل وواجب التوبة\\nتذكر سورة طه أن قوم موسى اتخذوا من حليهم عجلًا جسدًا له خوار، وأن السامري أضلهم، فرجع موسى غضبان أسفًا، وعاتب هارون ثم سأل السامري عن فعله. وتعرض الآيات إعلان بطلان العجل، وأن إلههم الله الذي لا إله إلا هو، ثم أمر موسى بإزالة أثر الفتنة. لا يصح اختزال القصة في لوم جماعي دون فهم مسؤولية كل شخص، فالقرآن يبين مواقف متعددة. ومن الدروس خطورة الغفلة بعد ظهور النعمة، وضرورة الرجوع إلى الوحي عند الاختلاف. المرجع: طه 83-98.",
    "الفصل الخامس عشر: دروس ممتدة من سيرة موسى\\nتجمع مقاطع قصة موسى عليه السلام معاني حفظ الله لعباده، والوفاء بالعهد، وطلب العون، والقول الحسن، والثبات أمام الظلم، والتوكل وقت الشدة، وشكر النعمة بعد النجاة. وقد وردت قصته في سور كثيرة، ولكل موضع سياقه ومقصده، لذلك لا تمثل هذه الفصول كل ما ورد عن موسى، بل تقدم مسارًا تعليميًا من أشهر أحداثه. وللتوسع ينبغي قراءة الآيات في مواضعها ومراجعة تفسير موثوق، وعدم نسبة تفاصيل القصص الشعبية إلى الوحي دون تثبت. المرجع: القصص 4-35؛ طه 9-98؛ الشعراء 10-68."
  )),
  QuranStory(5,"أصحاب الكهف","يذكر القرآن فتية آمنوا بربهم واعتزلوا قومهم، فآواهم الله إلى الكهف، ثم بعثهم ليظهر أمرهم آية للناس.","سورة الكهف: 9-26.",listOf("الثبات على الإيمان","صحبة الصالحين","طلب رحمة الله والهداية","أن علم الغيب الكامل لله"),"يلتزم الملخص بما ورد في الآيات، ولا يجزم بأسمائهم أو عددهم أو زمنهم إلا بدليل صحيح."),
  QuranStory(6,"مريم عليها السلام وبشارة عيسى","يعرض القرآن اعتزال مريم قومها، وبشارة الملائكة لها، وحملها بعيسى عليه السلام، ثم كلام عيسى في المهد بإذن الله.","سورة مريم: 16-36؛ وانظر آل عمران: 35-47.",listOf("عفة مريم وعبادتها","قدرة الله تعالى","براءة مريم مما رماها به قومها","عبودية عيسى لله ورسالته"),"يعتمد الملخص على الآيات، مع تجنب إضافة تفاصيل غير واردة في النص."),
  QuranStory(7,"وصايا لقمان لابنه","يعرض القرآن وصايا لقمان لابنه في التوحيد وبر الوالدين ومراقبة الله وإقامة الصلاة والأمر بالمعروف والتواضع.","سورة لقمان: 12-19.",listOf("النهي عن الشرك","الإحسان إلى الوالدين","مراقبة الله","الصلاة والصبر والتواضع"),"النص القرآني هو أصل القصة؛ لا نجزم بنسب أو تفاصيل لم يثبتها القرآن."),
  QuranStory(8,"سليمان والهدهد وملكة سبأ","يذكر القرآن خبر الهدهد عن قوم سبأ، ثم كتاب سليمان، ومجيء الملكة، وحوارها، وإعلانها إسلامها لله رب العالمين.","سورة النمل: 20-44.",listOf("التثبت من الأخبار","شكر نعمة الملك","الحكمة في الدعوة والحوار","إفراد الله بالعبادة"),"يعرض الملخص أحداث الآيات دون تعيين أسماء أو تفاصيل لم يذكرها القرآن."),
  QuranStory(9,"يونس عليه السلام","يذكر القرآن إرسال يونس، وذهابه مغاضبًا، ونداءه في الظلمات، فاستجاب الله له ونجاه، وذكر إيمان قومه.","سورة الصافات: 139-148؛ وانظر سورة الأنبياء: 87-88.",listOf("الرجوع إلى الله عند الخطأ","الدعاء والتسبيح","رحمة الله بعباده","أثر الإيمان"),"لا تضاف تفاصيل قصة الحوت أو مدة المكث إلا بنص ثابت؛ الملخص مبني على الآيات المحددة."),
  QuranStory(10,"أصحاب الفيل","يذكر القرآن ما فعل الله بأصحاب الفيل الذين قصدوا البيت، وكيف أبطل كيدهم وأرسل عليهم طيرًا أبابيل.","سورة الفيل: 1-5.",listOf("حفظ الله لبيته","ضعف كيد المعتدين أمام قدرة الله","التذكير بنعمة الله"),"يقتصر العرض على نص السورة، وأي تفاصيل تاريخية إضافية تحتاج تخريجًا مستقلًا."),
  QuranStory(11,"آدم عليه السلام وتوبة الله","بدأت قصة الإنسان بخلق آدم عليه السلام وتعليمه، ثم أمر الملائكة بالسجود تكريمًا، وامتنع إبليس استكبارًا. وبعد وقوع آدم وزوجه في المخالفة علّمهما الله كلمات التوبة فتاب عليهما. تذكر الآيات أن إبليس عدو للإنسان، وأن طريق النجاة هو اتباع هدى الله، وأن التوبة والرجوع إليه باب رحمة. لا تُحوّل القصة إلى تفاصيل تخمينية عن المكان أو الزمن؛ فالقرآن هو أساس العرض.","البقرة: 30-39؛ الأعراف: 11-27؛ طه: 115-123.",listOf("التواضع أمام أمر الله","الحذر من وسوسة إبليس","التوبة والرجوع","اتباع الهدى"),"مبني على الآيات المذكورة."),
  QuranStory(12,"قصة هود عليه السلام وقوم عاد","بعث الله هودًا إلى عاد يدعوهم إلى توحيد الله وترك التكبر. ذكّرهم بالنعم والقوة، وحثهم على الاستغفار والتوبة، لكن كثيرًا منهم جادلوا واستكبروا. وتذكر الآيات عاقبة التكذيب حين جاءهم العذاب، ونجّى الله هودًا ومن آمن معه. القصة دعوة إلى ألا تغر الإنسان القوة أو العمران، وإلى شكر النعمة والاستجابة للحق.","هود: 50-60؛ الأحقاف: 21-26.",listOf("التوحيد","شكر النعم","ترك الغرور بالقوة","الصبر في الدعوة"),"تفاصيل السرد مستندة إلى الآيات."),
  QuranStory(13,"صالح عليه السلام والناقة","دعا صالح عليه السلام قوم ثمود إلى عبادة الله، وطلبوا آية، فجاءتهم الناقة آيةً من الله. بيّن لهم صالح أن لها شربًا ولهم شرب يوم معلوم، وحذرهم من الاعتداء عليها. لكنهم عقروا الناقة وتحدوا أمر الله، فأخذتهم العاقبة. تعرض القصة معنى احترام آيات الله، وأن التحدي والاستكبار لا ينفع صاحبه.","هود: 61-68؛ الشعراء: 141-159.",listOf("التوحيد","الوفاء بالعهد","عدم الاستهانة بآيات الله","عاقبة الظلم"),"من القرآن الكريم."),
  QuranStory(14,"لوط عليه السلام ودعوة قومه","دعا لوط عليه السلام قومه إلى الطهر وترك الفاحشة، وأنكر عليهم ما كانوا يأتون من أعمال مخالفة للفطرة والشرع. لم يستجيبوا لدعوته بل هددوه، ثم جاءت الملائكة وأخبرته بنجاة المؤمنين والعاقبة التي حلّت بالمكذبين. يعرض القرآن القصة للعبرة والامتثال، ويؤكد أن الطاعة والابتعاد عن الفساد من أسباب النجاة.","هود: 77-83؛ الأعراف: 80-84.",listOf("الحياء والطهر","الابتعاد عن الفواحش","الصبر على الدعوة","الرجوع إلى شرع الله"),"تجنبنا تفاصيل غير ضرورية؛ العرض مبني على النص القرآني."),
  QuranStory(15,"شعيب عليه السلام وأهل مدين","أرسل شعيب إلى مدين يدعو إلى عبادة الله، وينهاهم عن بخس الناس حقوقهم في الكيل والميزان والفساد في الأرض. خاطبهم بالحكمة وبيّن أن الإصلاح لا يناقض التجارة، وأن الرزق لا يبرر الظلم. رفض كثير منهم دعوته، وتذكر الآيات نجاة شعيب والمؤمنين وهلاك المكذبين. القصة تتصل بالأمانة الاقتصادية والعدل في التعامل.","هود: 84-95؛ الأعراف: 85-93.",listOf("التوحيد","العدل في البيع","الأمانة","الإصلاح دون فساد"),"مستند إلى الآيات."),
  QuranStory(16,"داود عليه السلام والعدل","ذكر القرآن ما آتاه الله داود من الملك والحكمة، وأمره أن يحكم بين الناس بالحق وألا يتبع الهوى. كما وردت قصة الخصمين التي كانت تذكيرًا بالعدل والاستغفار. ويذكر القرآن تسبيح داود وتسخير الجبال والطير معه. ينبغي أن يقرأ المتعلم القصة من الآيات وأن يتجنب القصص الإضافية غير المحققة التي قد تُنسب إليه.","ص: 17-26؛ سبأ: 10-11.",listOf("العدل","الاستغفار","عدم اتباع الهوى","شكر نعم الله"),"المراجع: الآيات المحددة."),
  QuranStory(17,"أيوب عليه السلام والصبر","أثنى القرآن على أيوب عليه السلام في صبره ورجوعه إلى الله، وذكر دعاءه حين مسه الضر، ثم استجابة الله له وكشف ما به من ضر. كما ذكر من رحمته أن رد إليه أهله ومثلهم معهم. القصة تعلم أن الدعاء لا يتضمن اعتراضًا على القدر، وأن الصبر مع الدعاء والرجاء عبادة، وأن رحمة الله واسعة.","الأنبياء: 83-84؛ ص: 41-44.",listOf("الصبر","الدعاء","حسن الظن بالله","شكر العافية بعد البلاء"),"مبني على القرآن، دون تفاصيل إضافية عن المرض."),
  QuranStory(18,"زكريا عليه السلام وبشارة يحيى","دعا زكريا عليه السلام ربه دعاء خفيًا، وسأل ولدًا صالحًا مع تقدم سنه ووجود أسباب يراها الناس بعيدة. استجاب الله دعاءه وبشره بيحيى، وذكر القرآن صفات يحيى من البر والتقوى والحكمة. تبين القصة أن الدعاء عبادة وأن قدرة الله لا تحدها الأسباب المعتادة.","آل عمران: 38-41؛ مريم: 2-15.",listOf("الإخلاص في الدعاء","الرجاء بالله","صلاح الأبناء","التواضع لله"),"مراجع القصة: الآيات المذكورة."),
  QuranStory(19,"أم موسى وثقتها بالله","ذكر القرآن أن الله أوحى إلى أم موسى أن ترضعه ثم تضعه في اليم عند خوفها عليه، ووعدها أن يرده إليها ويجعله من المرسلين. التقطه آل فرعون، وأبى موسى المراضع، فكانت أخته سببًا في رجوعه إلى أمه. يصور هذا المقطع لطف الله وتدبيره، ويبين أن الخوف لا يمنع التوكل واتخاذ الأسباب.","القصص: 7-13.",listOf("التوكل مع الأخذ بالأسباب","الثقة بوعد الله","رحمة الأم","لطف الله في تدبير الأمور"),"سرد مطابق لمقطع القرآن."),
  QuranStory(20,"أصحاب الأخدود","ذكر القرآن أصحاب الأخدود في سورة البروج، وأشار إلى اضطهاد المؤمنين بسبب إيمانهم بالله وإلى وعيد الظالمين. تركز الآيات على ثبات المؤمنين وعلى عدالة الله، ولا تذكر تفاصيل كثيرة عن أسماء الأشخاص أو المكان. لذلك يعرض التطبيق المقطع القرآني ومقاصده دون إقحام روايات تاريخية غير متحقق منها.","سورة البروج: 4-10.",listOf("الثبات على الإيمان","رفض الظلم","الصبر","العدل الإلهي"),"أصل القصة في القرآن الكريم، والتفاصيل التاريخية الزائدة تحتاج تحققًا."),

  QuranStory(21,"أبو بكر الصديق رضي الله عنه","كان أبو بكر رضي الله عنه من السابقين إلى الإسلام، وصاحب النبي صلى الله عليه وسلم في الهجرة. اشتهر بالصدق والرفق والإنفاق، وتولى الخلافة بعد وفاة النبي فواجه أحداثًا عظيمة وحفظ وحدة المسلمين. تتناول هذه المادة مواقف ثابتة من سيرته مع الإحالة إلى مصادر التاريخ والحديث، وتجنب الروايات غير المحققة.","صحيح البخاري: أبواب فضائل الصحابة والهجرة؛ كتب السيرة والتاريخ المعتمدة.",listOf("الصدق","الوفاء","الإنفاق","الثبات في المواقف"),"تحتاج تفاصيل أحداث السيرة إلى مراجعة مصادرها."),
  QuranStory(22,"عمر بن الخطاب رضي الله عنه","أسلم عمر رضي الله عنه وصار من أصحاب النبي صلى الله عليه وسلم، وعُرف بالعدل والقوة في الحق. تولى الخلافة بعد أبي بكر، وتذكر كتب التاريخ توسع الدولة وتنظيم شؤون الناس في عهده. يعرض هذا الملخص مواقف من عدله ومحاسبته لنفسه، مع تمييز الروايات التاريخية التي تحتاج تحقيقًا.","صحيح البخاري: فضائل عمر؛ كتب التاريخ والسيرة.",listOf("العدل","الشجاعة في الحق","المحاسبة","الرحمة بالرعية"),"يراجع كل موقف تاريخي من مصدره."),
  QuranStory(23,"عثمان بن عفان رضي الله عنه","كان عثمان رضي الله عنه من السابقين إلى الإسلام، واشتهر بالحياء والإنفاق. ومن أبرز أعماله في خلافته جمع الناس على المصحف الإمام في زمنه، وفق ما تذكره المصادر الصحيحة. تعرض سيرته معنى خدمة القرآن والإنفاق على المسلمين.","صحيح البخاري، كتاب فضائل القرآن وفضائل عثمان؛ مصادر التاريخ.",listOf("الحياء","الإنفاق","خدمة القرآن","الصبر"),"مراجع الحديث والسيرة."),
  QuranStory(24,"علي بن أبي طالب رضي الله عنه","علي رضي الله عنه ابن عم النبي صلى الله عليه وسلم وصهره، ومن السابقين إلى الإسلام، وكان معروفًا بالعلم والشجاعة. تولى الخلافة في فترة اضطراب وفتن، ويعرض التطبيق سيرته مع التأكيد على حرمة الطعن والتهويل، وتوثيق الروايات التاريخية.","صحيح البخاري ومسلم: فضائل علي؛ كتب التاريخ المعتمدة.",listOf("العلم","الشجاعة","الزهد","الحكمة"),"يُراعى في الأحداث التاريخية التوثيق والإنصاف."),
  QuranStory(25,"بلال بن رباح رضي الله عنه","بلال رضي الله عنه من السابقين إلى الإسلام، وابتلي بسبب إيمانه، ثم أكرمه الله بصحبة النبي صلى الله عليه وسلم واشتهر بالأذان. تذكر المصادر فضله ومواقفه في الإسلام، وتعلم سيرته الثبات وكرامة المؤمن.","صحيح البخاري، فضائل بلال؛ كتب السيرة.",listOf("الثبات","الإخلاص","الصبر","العبادة"),"تستند المادة إلى الحديث والسيرة الموثوقة."),
  QuranStory(26,"خديجة رضي الله عنها","خديجة رضي الله عنها زوج النبي صلى الله عليه وسلم وأول من آمن به، ووقفت معه في بداية الدعوة. يذكر الحديث فضلها ومكانتها، وتعرض سيرتها الدعم والوفاء والثقة بالله، دون إطالة روايات غير ثابتة.","صحيح البخاري وصحيح مسلم: فضائل خديجة؛ كتب السيرة.",listOf("الوفاء","دعم الحق","الحكمة","الإيمان"),"مراجع الفضائل والسيرة."),
  QuranStory(27,"مصعب بن عمير رضي الله عنه","مصعب رضي الله عنه من السابقين إلى الإسلام، واختاره النبي صلى الله عليه وسلم لتعليم أهل المدينة قبل الهجرة. يعرض التطبيق أثر العلم والدعوة بالحكمة، مع الاستناد إلى روايات السيرة المعروفة ومراجعتها.","كتب السيرة: خبر بعث مصعب إلى المدينة؛ مصادر الحديث والتاريخ.",listOf("طلب العلم","التضحية","الحكمة في الدعوة","حسن الخلق"),"تفاصيل السيرة تُراجع من مصادرها."),
  QuranStory(28,"عبد الله بن مسعود رضي الله عنه","عبد الله بن مسعود رضي الله عنه من أصحاب النبي صلى الله عليه وسلم، واشتهر بعلمه بالقرآن وفقهه. يذكر الحديث فضله في القراءة، وتعرض سيرته ملازمة العلم والتعليم وأهمية التلقي.","صحيح البخاري: فضائل عبد الله بن مسعود وقراءة القرآن؛ مصادر تراجم الصحابة.",listOf("العلم","التواضع","تعليم القرآن","التلقي"),"مصادر الفضائل والتراجم."),
  QuranStory(29,"أبو هريرة رضي الله عنه","أبو هريرة رضي الله عنه من الصحابة المعروفين برواية الحديث، لازم النبي صلى الله عليه وسلم في مدة من حياته وحفظ أحاديث كثيرة. يعرض التطبيق سيرته وأهمية ضبط الرواية ومراجعة التخريج قبل اعتماد كل حديث.","صحيح البخاري وصحيح مسلم: فضائل أبي هريرة؛ كتب التراجم.",listOf("حفظ العلم","الحرص على السنة","التعليم","الأمانة"),"المادة تمهيدية، وأرقام الأحاديث تُراجع منفردة."),
  QuranStory(30,"سلمان الفارسي رضي الله عنه","سلمان الفارسي رضي الله عنه يبحث في سيرته عن الحق حتى وصل إلى الإسلام، وصار من أصحاب النبي صلى الله عليه وسلم. يذكر حديث الخندق رأيه في الحفر، وتعرض قصته معنى الاجتهاد في طلب الهداية والتعاون.","كتب السيرة في قصة سلمان والخندق؛ مصادر الحديث.",listOf("طلب الحق","الصبر","التعاون","التعلم"),"تفاصيل رحلة سلمان الطويلة تحتاج توثيقًا لكل رواية."),

  QuranStory(31,"إسماعيل عليه السلام","يذكر القرآن إسماعيل عليه السلام في سياق وفائه بوعده وصبره، كما يذكر مشاركته أباه إبراهيم في رفع قواعد البيت والدعاء. وتعرض الآيات طاعة الله وحسن الاستجابة.","مريم: 54-55؛ البقرة: 125-129.",listOf("الوفاء", "الصبر", "العبادة", "الدعاء"),"أصل العرض قرآني، ولا تضاف تفاصيل غير ثابتة."),
  QuranStory(32,"إدريس عليه السلام","ذكر القرآن إدريس عليه السلام ووصفه بالصدق والنبوة ورفعة المكانة. وتقتصر المادة على النص القرآني مع التنبيه إلى قلة التفاصيل الواردة.","مريم: 56-57.",listOf("الصدق", "الصبر على الطاعة", "مكانة الأنبياء"),"لا تجزم المادة بتفاصيل لم تثبت في القرآن أو السنة الصحيحة."),
  QuranStory(33,"إلياس عليه السلام","دعا إلياس قومه إلى عبادة الله وحده وترك ما كانوا يعبدون من دون الله. يذكر القرآن دعوته والثناء عليه وعلى أهل الإيمان.","الصافات: 123-132.",listOf("التوحيد", "الثبات", "اتباع الرسل"),"مبني على الآيات مع تجنب الروايات غير المحققة."),
  QuranStory(34,"اليسع عليه السلام","ذكر القرآن اليسع ضمن الأنبياء الذين فضلهم الله وهدى، ولا يفصل أحداث حياته؛ لذلك تعرض المادة مواضع ذكره والتعريف بمكانته.","الأنعام: 86؛ ص: 48.",listOf("الإيمان بالأنبياء", "الاقتداء بالهدى"),"تقتصر على النصوص القرآنية."),
  QuranStory(35,"ذو الكفل","ورد ذكر ذي الكفل في القرآن مع الثناء عليه بالصبر والصلاح. تتناول المادة الآيات التي ذكرته دون جزم بتفاصيل نسبه أو أحداث حياته.","الأنبياء: 85-86؛ ص: 48.",listOf("الصبر", "الصلاح", "الوفاء"),"تفاصيل هويته وأحداث حياته محل روايات؛ لا يجزم التطبيق بها."),
  QuranStory(36,"يوسف عليه السلام: العفو","في ختام مقاطع من سورة يوسف يظهر معنى العفو عند القدرة حين خاطب يوسف إخوته بالعفو، كما تتناول السورة تدبير الله وتغير الأحوال.","يوسف: 90-101.",listOf("العفو", "حسن الظن بالله", "الصبر"),"هذه مادة موضوعية من قصة يوسف وليست سردًا كاملًا."),
  QuranStory(37,"يوسف عليه السلام: الأمانة","يعرض القرآن من قصة يوسف معنى الأمانة والحكمة في تدبير شؤون الناس، وما جرى من ابتلاء ومواقف تتطلب صدقًا وثباتًا.","يوسف: 54-57؛  يوسف: 90.",listOf("الأمانة", "الحكمة", "الصبر"),"تلخيص موضوعي للآيات."),
  QuranStory(38,"موسى عليه السلام: لقاء الخضر","يروي القرآن لقاء موسى عليه السلام بالعبد الصالح وما تعلمه من الصبر على أمور لم تتضح حكمتها في البداية. وتؤكد المادة أدب طالب العلم والتواضع.","الكهف: 60-82.",listOf("الصبر في طلب العلم", "التواضع", "عدم التسرع بالحكم"),"تقتصر على أحداث الآيات، ولا تضيف تفاصيل غير موثقة."),
  QuranStory(39,"موسى عليه السلام: دعاء وفرعون","تذكر الآيات دعاء موسى عليه السلام حين كلف بالرسالة وطلب شرح صدره وتيسير أمره، وطلب أن يكون هارون معينًا له.","طه: 25-36؛ القصص: 29-35.",listOf("الدعاء", "طلب العون", "البلاغ الواضح"),"المادة موضوعية ومبنية على الآيات."),
  QuranStory(40,"موسى عليه السلام: بني إسرائيل","تتناول الآيات مواقف من بني إسرائيل بعد نجاتهم، وتذكر أهمية الوفاء والامتثال وعدم مقابلة النعمة بالجحود.","البقرة: 40-61؛ الأعراف: 138-141.",listOf("الشكر", "الوفاء", "التعلم من الأمم"),"عرض مختصر لمقاطع قرآنية."),
  QuranStory(41,"لقمان الحكيم","يعرض القرآن وصايا لقمان لابنه في التوحيد والبر والخلق والصلاة والصبر، وهي وصايا تربوية جامعة.","لقمان: 12-19.",listOf("التوحيد","بر الوالدين","الصلاة","التواضع","الصبر"),"مبني على الآيات القرآنية دون تفاصيل خارج النص."),
  QuranStory(42,"أصحاب الكهف","قصة فتية آمنوا بربهم فحفظ القرآن خبرهم، وتذكر الآيات مواقف من ثباتهم ودعائهم.","الكهف: 9-26.",listOf("الثبات على الإيمان","صحبة الخير","التوكل"),"يعرض ما جاء في القرآن ولا يجزم بأسماء أو أعداد غير منصوص عليها."),
  QuranStory(43,"مريم عليها السلام","تذكر سورة مريم عبادتها واصطفاءها وبشارة الملائكة لها وموقفها في قصة ولادة عيسى عليه السلام.","آل عمران: 35-47؛ مريم: 16-36.",listOf("العبادة","الثقة بالله","الصبر"),"مبني على القرآن."),
  QuranStory(44,"أصحاب الفيل","ذكر القرآن أصحاب الفيل وكيف رد الله كيدهم، وتؤكد السورة قدرة الله وحفظه.","الفيل: 1-5.",listOf("قدرة الله","عبرة التاريخ"),"سرد مقتصر على سورة الفيل."),
  QuranStory(45,"قارون","تتناول الآيات قصة قارون وما وقع بسبب التكبر والافتتان بالمال، وتذكر موقف أهل العلم وعاقبة البغي.","القصص: 76-82.",listOf("التواضع","عدم الاغترار بالمال","الشكر"),"يعتمد على الآيات."),
  QuranStory(46,"ملكة سبأ","تذكر سورة النمل خبر ملكة سبأ ومراسلتها لسليمان عليه السلام ثم موقفها من الدعوة وآيات الملك.","النمل: 20-44.",listOf("التثبت","الحكمة","الشورى"),"يعتمد على النص القرآني."),
  QuranStory(47,"أصحاب السبت","ذكر القرآن ابتلاء أصحاب السبت ومخالفة أمر الله، والعبرة في الالتزام والاحتراز من الحيل.","الأعراف: 163-166.",listOf("الامتثال","العبرة من الأمم"),"تجنب التفاصيل التي لا تثبت."),
  QuranStory(48,"أصحاب الجنة","تذكر سورة القلم قصة أصحاب الجنة الذين أرادوا منع حق المحتاجين، فكانت القصة عبرة في الشكر والإنصاف.","القلم: 17-33.",listOf("الشكر","الإنصاف","الصدقة"),"مبني على الآيات."),
  QuranStory(49,"السامري","تعرض سورة طه فتنة بني إسرائيل في غياب موسى عليه السلام وموقف السامري، مع التحذير من اتباع الباطل.","طه: 83-98.",listOf("اتباع الحق","الحذر من الفتن"),"مقتصر على القرآن."),
  QuranStory(50,"أصحاب الأخدود","ذكر القرآن أصحاب الأخدود وابتلاء المؤمنين وثباتهم، وتتناول المادة الآيات دون تفصيل تاريخي غير موثق.","البروج: 4-10.",listOf("الثبات","الإيمان","العدل"),"مبني على القرآن مع عدم توسع في الروايات.")


)

